// Generated by kfx from KFX-0 source: edit that, and regenerate (PLAN.md, section 1).

use kayak_rt::*;
use super::*;

// kfx.kfx: KFX-0 to Rust, written in KFX-0.
//
// KFX-0 is the part of FX-26 this file is written in (PLAN.md, section 2). Fixpt
// runs this file to make boot/src/kfx.rs (stage 0); the Rust built from
// that runs it again, and must make the same file (PLAN.md, section 1).
//
// `compile` takes a program's text and gives its Rust. It reads the text
// into `sexp`s, notes the program's datatypes and constants, and writes
// Rust onto a list of characters, newest first, which is reversed once at
// the end.

pub type Chars = List<char>;

pub type Strings = List<Str>;

// Lists, of anything
pub fn map<A: Copy + 'static, B: Copy + 'static>(f: &'static dyn Fn(A) -> B, xs: List<A>) -> List<B> {
    if null_p(xs) {
        nil()
    } else {
        cons(f(car(xs)), map(f, cdr(xs)))
    }
}

pub fn any_p<A: Copy + 'static>(p: &'static dyn Fn(A) -> bool, xs: List<A>) -> bool {
    (not(null_p(xs)) && (p(car(xs)) || any_p(p, cdr(xs))))
}

pub fn size_from<A: Copy + 'static>(mut xs: List<A>, mut n: i64) -> i64 {
    loop {
        if null_p(xs) {
            return n;
        } else {
            (xs, n) = (cdr(xs), i64_plus(n, 1i64));
            continue;
        }
    }
}

pub fn size<A: Copy + 'static>(xs: List<A>) -> i64 {
    size_from(xs, 0i64)
}

pub fn last<A: Copy + 'static>(mut xs: List<A>) -> A {
    loop {
        if null_p(cdr(xs)) {
            return car(xs);
        } else {
            xs = cdr(xs);
            continue;
        }
    }
}

// Characters and strings
pub fn rev_onto(mut xs: Chars, mut acc: Chars) -> Chars {
    loop {
        if null_p(xs) {
            return acc;
        } else {
            (xs, acc) = (cdr(xs), cons(car(xs), acc));
            continue;
        }
    }
}

pub fn rev_to_string(acc: Chars) -> Str {
    list_to_string(rev_onto(acc, nil()))
}

pub fn string_chars_from(s: Str, i: i64, n: i64) -> Chars {
    if i64_lt(i, n) {
        cons(string_ref_i64(s, i), string_chars_from(s, i64_plus(i, 1i64), n))
    } else {
        nil()
    }
}

pub fn string_chars(s: Str) -> Chars {
    string_chars_from(s, 0i64, string_length_i64(s))
}

pub fn put_from(mut s: Str, mut i: i64, mut n: i64, mut acc: Chars) -> Chars {
    loop {
        if i64_lt(i, n) {
            (i, acc) = (i64_plus(i, 1i64), cons(string_ref_i64(s, i), acc));
            continue;
        } else {
            return acc;
        }
    }
}

/// Adds `s` to the output `acc`.
pub fn put(s: Str, acc: Chars) -> Chars {
    put_from(s, 0i64, string_length_i64(s), acc)
}

/// Each of `xs` added to `acc` by `each`, separated by `sep`.
pub fn put_sep<A: Copy + 'static>(mut each: &'static dyn Fn(A, Chars) -> Chars, mut sep: Str, mut xs: List<A>, mut acc: Chars) -> Chars {
    loop {
        if null_p(xs) {
            return acc;
        } else if null_p(cdr(xs)) {
            return each(car(xs), acc);
        } else {
            (xs, acc) = (cdr(xs), put(sep, each(car(xs), acc)));
            continue;
        }
    }
}

pub fn string_member_p(s: Str, xs: Strings) -> bool {
    if null_p(xs) {
        false
    } else {
        (string_eq_p(s, car(xs)) || string_member_p(s, cdr(xs)))
    }
}

// Reading
pub enum Sexp {
    Sym(Str),
    Str(Str),
    Num(i64),
    Chr(char),
    Lst(List<&'static Sexp>),
}

pub fn sym(f0: Str) -> &'static Sexp {
    alloc(Sexp::Sym(f0))
}

pub fn str(f0: Str) -> &'static Sexp {
    alloc(Sexp::Str(f0))
}

pub fn num(f0: i64) -> &'static Sexp {
    alloc(Sexp::Num(f0))
}

pub fn chr(f0: char) -> &'static Sexp {
    alloc(Sexp::Chr(f0))
}

pub fn lst(f0: List<&'static Sexp>) -> &'static Sexp {
    alloc(Sexp::Lst(f0))
}

pub type Sexps = List<&'static Sexp>;

// A datum, and the text after it.
pub enum Got {
    Got(&'static Sexp, Chars),
}

pub fn got(f0: &'static Sexp, f1: Chars) -> &'static Got {
    alloc(Got::Got(f0, f1))
}

pub enum Gots {
    Gots(Sexps, Chars),
}

pub fn gots(f0: Sexps, f1: Chars) -> &'static Gots {
    alloc(Gots::Gots(f0, f1))
}

pub enum Tok {
    Tok(Str, Chars),
}

pub fn tok(f0: Str, f1: Chars) -> &'static Tok {
    alloc(Tok::Tok(f0, f1))
}

pub fn skip_line(mut cs: Chars) -> Chars {
    loop {
        if null_p(cs) {
            return cs;
        } else if char_eq_p(car(cs), '\n') {
            return cdr(cs);
        } else {
            cs = cdr(cs);
            continue;
        }
    }
}

/// Skips whitespace and comments.
pub fn skip(mut cs: Chars) -> Chars {
    loop {
        if null_p(cs) {
            return cs;
        } else if char_whitespace_p(car(cs)) {
            cs = cdr(cs);
            continue;
        } else if char_eq_p(car(cs), ';') {
            cs = skip_line(cdr(cs));
            continue;
        } else {
            return cs;
        }
    }
}

pub fn delimiter_p(c: char) -> bool {
    (char_whitespace_p(c) || char_eq_p(c, '(') || char_eq_p(c, ')') || char_eq_p(c, '"') || char_eq_p(c, ';'))
}

/// A token's characters, onto `acc`, newest first.
pub fn token_chars(mut cs: Chars, mut acc: Chars) -> &'static Tok {
    loop {
        if (null_p(cs) || delimiter_p(car(cs))) {
            return tok(rev_to_string(acc), cs);
        } else {
            (cs, acc) = (cdr(cs), cons(car(cs), acc));
            continue;
        }
    }
}

pub fn unescape(c: char) -> char {
    match c {
        'n' => {
            '\n'
        }
        't' => {
            '\t'
        }
        _ => {
            c
        }
    }
}

/// A string's characters, after its opening quote.
pub fn string_body(mut cs: Chars, mut acc: Chars) -> &'static Tok {
    loop {
        if null_p(cs) {
            return error("kfx: a string is not closed");
        } else if char_eq_p(car(cs), '"') {
            return tok(rev_to_string(acc), cdr(cs));
        } else if char_eq_p(car(cs), '\\') {
            (cs, acc) = (cdr(cdr(cs)), cons(unescape(car(cdr(cs))), acc));
            continue;
        } else {
            (cs, acc) = (cdr(cs), cons(car(cs), acc));
            continue;
        }
    }
}

/// Digits onto `n`, negated: so that -9223372036854775808, whose
/// magnitude is no i64, reads. A literal past an i64 is refused, as FX-26
/// refuses it where an i64 is expected.
pub fn digits_value(mut cs: Chars, mut n: i64) -> i64 {
    loop {
        if null_p(cs) {
            return n;
        } else {
            let d = i64_minus(char_to_i64(car(cs)), 48i64);
            if (i64_lt(n, -922337203685477580i64) || (i64_eq(n, -922337203685477580i64) && i64_gt(d, 8i64))) {
                return error("kfx: a literal past an i64");
            } else {
                (cs, n) = (cdr(cs), i64_minus(i64_star(n, 10i64), d));
                continue;
            }
        }
    }
}

pub fn numeric_p(cs: Chars) -> bool {
    (not(null_p(cs)) && (char_numeric_p(car(cs)) || (char_eq_p(car(cs), '-') && not(null_p(cdr(cs))) && char_numeric_p(car(cdr(cs))))))
}

pub fn token_atom(s: Str) -> &'static Sexp {
    let cs = string_chars(s);
    if not(numeric_p(cs)) {
        sym(s)
    } else if char_eq_p(car(cs), '-') {
        num(digits_value(cdr(cs), 0i64))
    } else {
        let negated = digits_value(cs, 0i64);
        if i64_eq(negated, -9223372036854775808i64) {
            error("kfx: a literal past an i64")
        } else {
            num(i64_minus(0i64, negated))
        }
    }
}

pub fn char_named(s: Str) -> char {
    if i64_eq(string_length_i64(s), 1i64) {
        string_ref_i64(s, 0i64)
    } else if string_eq_p(s, "space") {
        ' '
    } else if string_eq_p(s, "newline") {
        '\n'
    } else if string_eq_p(s, "tab") {
        '\t'
    } else {
        error(string_append("kfx: no character is named ", s))
    }
}

pub fn read_datum(cs: Chars) -> &'static Got {
    let c = car(cs);
    if char_eq_p(c, '(') {
        let tagcase_ = read_items(cdr(cs));
        match *tagcase_ {
            Gots::Gots(xs, after) => {
                got(lst(xs), after)
            }
        }
    } else if char_eq_p(c, ')') {
        error("kfx: a ) with no (")
    } else if char_eq_p(c, '"') {
        let tagcase_ = string_body(cdr(cs), nil());
        match *tagcase_ {
            Tok::Tok(s, after) => {
                got(str(s), after)
            }
        }
    } else if (char_eq_p(c, '#') && not(null_p(cdr(cs))) && char_eq_p(car(cdr(cs)), '\\')) {
        let name = cdr(cdr(cs));
        let tagcase_ = token_chars(cdr(name), cons(car(name), nil()));
        match *tagcase_ {
            Tok::Tok(s, after) => {
                got(chr(char_named(s)), after)
            }
        }
    } else {
        let tagcase_ = token_chars(cs, nil());
        match *tagcase_ {
            Tok::Tok(s, after) => {
                got(token_atom(s), after)
            }
        }
    }
}

pub fn read_items(cs: Chars) -> &'static Gots {
    let cs = skip(cs);
    if null_p(cs) {
        error("kfx: a ( with no )")
    } else if char_eq_p(car(cs), ')') {
        gots(nil(), cdr(cs))
    } else {
        let tagcase_ = read_datum(cs);
        match *tagcase_ {
            Got::Got(x, after) => {
                let tagcase_ = read_items(after);
                match *tagcase_ {
                    Gots::Gots(xs, rest) => {
                        gots(cons(x, xs), rest)
                    }
                }
            }
        }
    }
}

pub fn read_all(cs: Chars) -> Sexps {
    let cs = skip(cs);
    if null_p(cs) {
        nil()
    } else {
        let tagcase_ = read_datum(cs);
        match *tagcase_ {
            Got::Got(x, after) => {
                cons(x, read_all(after))
            }
        }
    }
}

// Taking `sexp`s apart
pub fn sym_name(e: &'static Sexp) -> Str {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(s) => {
            s
        }
        _ => {
            let other = tagcase_;
            error("kfx: a name is expected")
        }
    }
}

pub fn sym_is_p(e: &'static Sexp, s: Str) -> bool {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(n) => {
            string_eq_p(n, s)
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

pub fn items(e: &'static Sexp) -> Sexps {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Lst(xs) => {
            xs
        }
        _ => {
            let other = tagcase_;
            error("kfx: a list is expected")
        }
    }
}

pub fn head_is_p(e: &'static Sexp, s: Str) -> bool {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Lst(xs) => {
            (not(null_p(xs)) && sym_is_p(car(xs), s))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

pub fn second(xs: Sexps) -> &'static Sexp {
    car(cdr(xs))
}

pub fn third(xs: Sexps) -> &'static Sexp {
    car(cdr(cdr(xs)))
}

pub fn fourth(xs: Sexps) -> &'static Sexp {
    car(cdr(cdr(cdr(xs))))
}

// Names
pub fn rust_keyword_p(s: Str) -> bool {
    string_member_p(s, cons("as", cons("async", cons("await", cons("box", cons("break", cons("const", cons("continue", cons("do", cons("dyn", cons("else", cons("enum", cons("extern", cons("false", cons("final", cons("fn", cons("for", cons("gen", cons("if", cons("impl", cons("in", cons("let", cons("loop", cons("macro", cons("match", cons("mod", cons("move", cons("mut", cons("override", cons("priv", cons("pub", cons("ref", cons("return", cons("static", cons("struct", cons("trait", cons("true", cons("try", cons("type", cons("typeof", cons("unsafe", cons("unsized", cons("use", cons("virtual", cons("where", cons("while", cons("yield", nil())))))))))))))))))))))))))))))))))))))))))))))))
}

pub fn mangle_char(c: char) -> Str {
    match c {
        '-' => {
            "_"
        }
        '?' => {
            "_p"
        }
        '!' => {
            "_x"
        }
        '+' => {
            "_plus"
        }
        '*' => {
            "_star"
        }
        '/' => {
            "_slash"
        }
        '<' => {
            "_lt"
        }
        '>' => {
            "_gt"
        }
        '=' => {
            "_eq"
        }
        '%' => {
            "_pct"
        }
        _ => {
            char_to_string(c)
        }
    }
}

pub fn mangle_chars(mut cs: Chars, mut acc: Chars) -> Chars {
    loop {
        if null_p(cs) {
            return acc;
        } else if (char_eq_p(car(cs), '-') && not(null_p(cdr(cs))) && char_eq_p(car(cdr(cs)), '>')) {
            (cs, acc) = (cdr(cdr(cs)), put("_to_", acc));
            continue;
        } else if (char_eq_p(car(cs), '-') && null_p(cdr(cs))) {
            return put("_minus", acc);
        } else {
            (cs, acc) = (cdr(cs), put(mangle_char(car(cs)), acc));
            continue;
        }
    }
}

/// A KFX name as a Rust value's: `string->list` is `string_to_list`.
pub fn mangle(s: Str) -> Str {
    if string_eq_p(s, "-") {
        "_minus"
    } else if rust_keyword_p(s) {
        string_append("r#", s)
    } else {
        rev_to_string(mangle_chars(string_chars(s), nil()))
    }
}

pub fn camel_chars(mut cs: Chars, mut up: bool, mut acc: Chars) -> Chars {
    loop {
        if null_p(cs) {
            return acc;
        } else if char_eq_p(car(cs), '-') {
            (cs, up) = (cdr(cs), true);
            continue;
        } else if up {
            (cs, up, acc) = (cdr(cs), false, cons(char_upcase(car(cs)), acc));
            continue;
        } else {
            (cs, up, acc) = (cdr(cs), false, cons(car(cs), acc));
            continue;
        }
    }
}

/// A KFX name as a Rust type's: `got-list` is `GotList`.
pub fn camel(s: Str) -> Str {
    rev_to_string(camel_chars(string_chars(s), true, nil()))
}

// What the program defines

// A tag, and its datatype's name.
pub enum Tagof {
    Tagof(Str, Str),
}

pub fn tagof(f0: Str, f1: Str) -> &'static Tagof {
    alloc(Tagof::Tagof(f0, f1))
}

pub type Tagofs = List<&'static Tagof>;

// Datatypes' names, their tags, constants (definitions not of procedures),
// and the names bound where an expression is. A name named as a value is
// a local, a constant (a call of its `fn`), or else a global procedure (a
// reference to its `fn`, the program's or kayak-rt's).
pub enum Ctx {
    Ctx(Strings, Tagofs, Strings, Strings),
}

pub fn ctx(f0: Strings, f1: Tagofs, f2: Strings, f3: Strings) -> &'static Ctx {
    alloc(Ctx::Ctx(f0, f1, f2, f3))
}

pub fn ctx_datatypes(c: &'static Ctx) -> Strings {
    let tagcase_ = c;
    match *tagcase_ {
        Ctx::Ctx(ds, ts, ks, ls) => {
            ds
        }
    }
}

pub fn ctx_tags(c: &'static Ctx) -> Tagofs {
    let tagcase_ = c;
    match *tagcase_ {
        Ctx::Ctx(ds, ts, ks, ls) => {
            ts
        }
    }
}

pub fn ctx_constants(c: &'static Ctx) -> Strings {
    let tagcase_ = c;
    match *tagcase_ {
        Ctx::Ctx(ds, ts, ks, ls) => {
            ks
        }
    }
}

pub fn ctx_locals(c: &'static Ctx) -> Strings {
    let tagcase_ = c;
    match *tagcase_ {
        Ctx::Ctx(ds, ts, ks, ls) => {
            ls
        }
    }
}

pub fn strings_onto(mut xs: Strings, mut ys: Strings) -> Strings {
    loop {
        if null_p(xs) {
            return ys;
        } else {
            (xs, ys) = (cdr(xs), cons(car(xs), ys));
            continue;
        }
    }
}

/// `c`, where `names` are bound too.
pub fn with_locals(c: &'static Ctx, names: Strings) -> &'static Ctx {
    let tagcase_ = c;
    match *tagcase_ {
        Ctx::Ctx(ds, ts, ks, ls) => {
            ctx(ds, ts, ks, strings_onto(names, ls))
        }
    }
}

pub fn tag_datatype(mut tag: Str, mut ts: Tagofs) -> Str {
    loop {
        if null_p(ts) {
            return error(string_append("kfx: not a datatype's tag: ", tag));
        } else {
            let tagcase_ = car(ts);
            match *tagcase_ {
                Tagof::Tagof(t, d) => {
                    if string_eq_p(t, tag) {
                        return d;
                    } else {
                        ts = cdr(ts);
                        continue;
                    }
                }
            }
        }
    }
}

pub fn note_tags(mut variants: Sexps, mut d: Str, mut ts: Tagofs) -> Tagofs {
    loop {
        if null_p(variants) {
            return ts;
        } else {
            (variants, ts) = (cdr(variants), cons(tagof(sym_name(car(items(car(variants)))), d), ts));
            continue;
        }
    }
}

pub fn procedure_p(e: &'static Sexp) -> bool {
    (head_is_p(e, "lambda") || head_is_p(e, "plambda"))
}

pub fn note(form: &'static Sexp, c: &'static Ctx) -> &'static Ctx {
    let tagcase_ = c;
    match *tagcase_ {
        Ctx::Ctx(ds, ts, ks, ls) => {
            if head_is_p(form, "define-datatype") {
                let d = sym_name(second(items(form)));
                ctx(cons(d, ds), note_tags(cdr(cdr(items(form))), d, ts), ks, ls)
            } else if (head_is_p(form, "define") && i64_eq(size(items(form)), 4i64) && not(procedure_p(fourth(items(form))))) {
                ctx(ds, ts, cons(sym_name(second(items(form))), ks), ls)
            } else {
                c
            }
        }
    }
}

pub fn collect(mut forms: Sexps, mut c: &'static Ctx) -> &'static Ctx {
    loop {
        if null_p(forms) {
            return c;
        } else {
            (forms, c) = (cdr(forms), note(car(forms), c));
            continue;
        }
    }
}

// Writing Rust
pub fn escape_char(c: char, q: char) -> Str {
    if char_eq_p(c, '\\') {
        "\\\\"
    } else if char_eq_p(c, q) {
        string_append("\\", char_to_string(c))
    } else if char_eq_p(c, '\n') {
        "\\n"
    } else if char_eq_p(c, '\t') {
        "\\t"
    } else {
        char_to_string(c)
    }
}

/// `cs` as the inside of a Rust literal delimited by `q`.
pub fn put_escaped(mut cs: Chars, mut q: char, mut acc: Chars) -> Chars {
    loop {
        if null_p(cs) {
            return acc;
        } else {
            (cs, acc) = (cdr(cs), put(escape_char(car(cs), q), acc));
            continue;
        }
    }
}

/// A type. A name that is no base type or datatype is a type abbreviation
/// or a type variable, either way a Rust type of the same name.
pub fn put_type(c: &'static Ctx, t: &'static Sexp, acc: Chars) -> Chars {
    let tagcase_ = t;
    match *tagcase_ {
        Sexp::Sym(s) => {
            if string_eq_p(s, "i64") {
                put("i64", acc)
            } else if string_eq_p(s, "int") {
                error("kfx: KFX has no int, whose + makes a bignum; write i64, whose i64+ wraps")
            } else if string_eq_p(s, "bool") {
                put("bool", acc)
            } else if string_eq_p(s, "char") {
                put("char", acc)
            } else if string_eq_p(s, "unit") {
                put("()", acc)
            } else if string_eq_p(s, "void") {
                put("!", acc)
            } else if string_eq_p(s, "string") {
                put("Str", acc)
            } else if string_member_p(s, ctx_datatypes(c)) {
                put(camel(s), put("&'static ", acc))
            } else {
                put(camel(s), acc)
            }
        }
        Sexp::Lst(xs) => {
            if sym_is_p(car(xs), "listof") {
                put(">", put_type(c, second(xs), put("List<", acc)))
            } else if sym_is_p(car(xs), "subr") {
                let acc = put("&'static dyn Fn(", acc);
                let acc = put_types(c, items(third(xs)), acc);
                let acc = put(") -> ", acc);
                put_type(c, fourth(xs), acc)
            } else if sym_is_p(car(xs), "poly") {
                error("kfx: a poly type is only a definition's, at its top")
            } else {
                error("kfx: a type KFX-0 does not have")
            }
        }
        _ => {
            let other = tagcase_;
            error("kfx: a type KFX-0 does not have")
        }
    }
}

/// Types, separated by commas.
pub fn put_types(c: &'static Ctx, types: Sexps, acc: Chars) -> Chars {
    put_sep(lambda2(move |t: &'static Sexp, acc| {
        put_type(c, t, acc)
    }), ", ", types, acc)
}

pub fn put_var(c: &'static Ctx, s: Str, acc: Chars) -> Chars {
    if string_eq_p(s, "#t") {
        put("true", acc)
    } else if string_eq_p(s, "#f") {
        put("false", acc)
    } else if string_eq_p(s, "#u") {
        put("()", acc)
    } else if string_member_p(s, ctx_locals(c)) {
        put(mangle(s), acc)
    } else if (string_eq_p(s, "nil") || string_member_p(s, ctx_constants(c))) {
        put("()", put(mangle(s), acc))
    } else {
        put(mangle(s), put("&", acc))
    }
}

pub fn put_spaces(mut k: i64, mut acc: Chars) -> Chars {
    loop {
        if i64_eq(k, 0i64) {
            return acc;
        } else {
            (k, acc) = (i64_minus(k, 1i64), put("    ", acc));
            continue;
        }
    }
}

/// A new line, indented `n` levels.
pub fn put_nl(n: i64, acc: Chars) -> Chars {
    put_spaces(n, put("\n", acc))
}

/// A string literal where a body's value is not taken is a comment: KFX's
/// comments are strings, since `;` comments do not survive reading. Each of
/// its lines is written after `prefix` (`//` or `///`), leading spaces
/// dropped; `fresh` says no prefix has been written for this line yet.
pub fn put_comment(mut cs: Chars, mut prefix: Str, mut n: i64, mut fresh: bool, mut acc: Chars) -> Chars {
    loop {
        if null_p(cs) {
            return acc;
        } else if char_eq_p(car(cs), '\n') {
            (cs, fresh, acc) = (cdr(cs), true, put_nl(n, if fresh {
                put(prefix, acc)
            } else {
                acc
            }));
            continue;
        } else if (fresh && char_eq_p(car(cs), ' ')) {
            (cs, fresh) = (cdr(cs), true);
            continue;
        } else if fresh {
            (cs, fresh, acc) = (cdr(cs), false, cons(car(cs), put(" ", put(prefix, acc))));
            continue;
        } else {
            (cs, fresh, acc) = (cdr(cs), false, cons(car(cs), acc));
            continue;
        }
    }
}

pub fn comment_p(e: &'static Sexp) -> bool {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Str(s) => {
            true
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

pub fn comment_text(e: &'static Sexp) -> Str {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Str(s) => {
            s
        }
        _ => {
            let other = tagcase_;
            ""
        }
    }
}

/// Names, separated by commas.
pub fn put_names(xs: Sexps, acc: Chars) -> Chars {
    put_sep(lambda2(move |x: &'static Sexp, acc| {
        put(mangle(sym_name(x)), acc)
    }), ", ", xs, acc)
}

// Self tail calls. Rust has no tail calls, so a procedure that calls itself
// last is a `loop`: the call assigns its parameters and `continue`s, and
// everything else it could end with is `return`ed.
pub enum Tail {
    Value(),
    Returns(Str, Strings, bool),
}

pub fn value() -> &'static Tail {
    alloc(Tail::Value())
}

pub fn returns(f0: Str, f1: Strings, f2: bool) -> &'static Tail {
    alloc(Tail::Returns(f0, f1, f2))
}

// `value`: an expression whose value is used. `returns`: the last thing a
// looping procedure does, with the procedure's name and parameters; the
// flag is false where a binding hides a parameter, since an assignment
// would then reach the binding, not the parameter.
pub fn binding_name(binding: &'static Sexp) -> Str {
    sym_name(car(items(binding)))
}

/// A lambda's parameter's name: it is `x` or `(x T)`.
pub fn param_name(param: &'static Sexp) -> Str {
    sym_name({
        let tagcase_ = param;
        match *tagcase_ {
            Sexp::Lst(xs) => {
                car(xs)
            }
            _ => {
                let other = tagcase_;
                other
            }
        }
    })
}

/// `t`, under bindings of `names`.
pub fn hide(t: &'static Tail, names: Strings) -> &'static Tail {
    let tagcase_ = t;
    match *tagcase_ {
        Tail::Returns(f, ps, live) => {
            if (live && any_p(lambda1(move |x: Str| {
                string_member_p(x, ps)
            }), names)) {
                returns(f, ps, false)
            } else {
                t
            }
        }
        _ => {
            let other = tagcase_;
            t
        }
    }
}

pub fn returns_p(t: &'static Tail) -> bool {
    let tagcase_ = t;
    match *tagcase_ {
        Tail::Returns(f, ps, live) => {
            true
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

pub fn self_call_p(t: &'static Tail, e: &'static Sexp) -> bool {
    let tagcase_ = t;
    match *tagcase_ {
        Tail::Returns(f, ps, live) => {
            (live && head_is_p(e, f) && i64_eq(size(cdr(items(e))), size(ps)))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// The forms whose last parts stand where they do.
pub fn control_p(e: &'static Sexp) -> bool {
    (head_is_p(e, "if") || head_is_p(e, "cond") || head_is_p(e, "case") || head_is_p(e, "tagcase") || head_is_p(e, "let") || head_is_p(e, "let*") || head_is_p(e, "begin"))
}

/// Whether `e`, standing at `t`, makes a self tail call: whether its
/// procedure loops.
pub fn tail_calls_p(mut t: &'static Tail, mut e: &'static Sexp) -> bool {
    loop {
        if self_call_p(t, e) {
            return true;
        } else if head_is_p(e, "if") {
            let xs = cdr(items(e));
            return (tail_calls_p(t, second(xs)) || tail_calls_p(t, third(xs)));
        } else if head_is_p(e, "cond") {
            return arms_tail_calls_p(t, cdr(items(e)));
        } else if head_is_p(e, "case") {
            return arms_tail_calls_p(t, cdr(cdr(items(e))));
        } else if head_is_p(e, "tagcase") {
            return tag_arms_tail_calls_p(t, cdr(cdr(items(e))));
        } else if (head_is_p(e, "let") || head_is_p(e, "let*")) {
            let xs = cdr(items(e));
            (t, e) = (hide(t, map(&binding_name, items(car(xs)))), last(cdr(xs)));
            continue;
        } else if head_is_p(e, "begin") {
            e = last(cdr(items(e)));
            continue;
        } else {
            return false;
        }
    }
}

/// A `cond`'s clauses, or a `case`'s arms: each a test or data, then a body.
pub fn arms_tail_calls_p(mut t: &'static Tail, mut arms: Sexps) -> bool {
    loop {
        if null_p(arms) {
            return false;
        } else if tail_calls_p(t, last(cdr(items(car(arms))))) {
            return true;
        } else {
            arms = cdr(arms);
            continue;
        }
    }
}

pub fn tag_arms_tail_calls_p(t: &'static Tail, arms: Sexps) -> bool {
    if null_p(arms) {
        false
    } else {
        let arm = items(car(arms));
        let bound = if sym_is_p(car(arm), "else") {
            cons(sym_name(second(arm)), nil())
        } else {
            map(&sym_name, items(second(arm)))
        };
        (tail_calls_p(hide(t, bound), last(cdr(cdr(arm)))) || tag_arms_tail_calls_p(t, cdr(arms)))
    }
}

pub enum Assign {
    Assign(Strings, Sexps),
}

pub fn assign(f0: Strings, f1: Sexps) -> &'static Assign {
    alloc(Assign::Assign(f0, f1))
}

/// The parameters a self tail call changes, and their new values: an
/// argument that is the parameter itself changes nothing.
pub fn changes(ps: Strings, args: Sexps) -> &'static Assign {
    if null_p(ps) {
        assign(nil(), nil())
    } else {
        let tagcase_ = changes(cdr(ps), cdr(args));
        match *tagcase_ {
            Assign::Assign(names, values) => {
                if sym_is_p(car(args), car(ps)) {
                    assign(names, values)
                } else {
                    assign(cons(car(ps), names), cons(car(args), values))
                }
            }
        }
    }
}

/// Names, mangled, separated by commas.
pub fn put_strings(xs: Strings, acc: Chars) -> Chars {
    put_sep(lambda2(move |x: Str, acc| {
        put(mangle(x), acc)
    }), ", ", xs, acc)
}

// Every writer of an expression takes `n`, the indentation of the line it
// starts on, and `t`, where the expression stands.
pub fn put_exp(c: &'static Ctx, e: &'static Sexp, n: i64, t: &'static Tail, acc: Chars) -> Chars {
    if self_call_p(t, e) {
        put_continue(c, cdr(items(e)), n, t, acc)
    } else if (returns_p(t) && not(control_p(e))) {
        put(";", put_exp(c, e, n, value(), put("return ", acc)))
    } else {
        let tagcase_ = e;
        match *tagcase_ {
            Sexp::Num(k) => {
                put("i64", put(i64_to_string(k), acc))
            }
            Sexp::Chr(ch) => {
                put("'", put_escaped(cons(ch, nil()), '\'', put("'", acc)))
            }
            Sexp::Str(s) => {
                put("\"", put_escaped(string_chars(s), '"', put("\"", acc)))
            }
            Sexp::Sym(s) => {
                put_var(c, s, acc)
            }
            Sexp::Lst(xs) => {
                let tagcase_ = car(xs);
                match *tagcase_ {
                    Sexp::Sym(h) => {
                        put_form(c, e, h, cdr(xs), n, t, acc)
                    }
                    _ => {
                        let head = tagcase_;
                        let acc = put("(", acc);
                        let acc = put_exp(c, head, n, value(), acc);
                        let acc = put(")(", acc);
                        put(")", if null_p(cdr(xs)) {
                            acc
                        } else {
                            put_joined(c, cdr(xs), ", ", n, acc)
                        })
                    }
                }
            }
        }
    }
}

/// A self tail call: the parameters it changes assigned, all at once.
pub fn put_continue(c: &'static Ctx, args: Sexps, n: i64, t: &'static Tail, acc: Chars) -> Chars {
    let tagcase_ = t;
    match *tagcase_ {
        Tail::Returns(f, ps, live) => {
            let tagcase_ = changes(ps, args);
            match *tagcase_ {
                Assign::Assign(names, values) => {
                    let acc = if null_p(names) {
                        acc
                    } else if null_p(cdr(names)) {
                        let acc = put(mangle(car(names)), acc);
                        let acc = put(" = ", acc);
                        let acc = put_exp(c, car(values), n, value(), acc);
                        put_nl(n, put(";", acc))
                    } else {
                        let acc = put("(", acc);
                        let acc = put_strings(names, acc);
                        let acc = put(") = (", acc);
                        let acc = put_joined(c, values, ", ", n, acc);
                        put_nl(n, put(");", acc))
                    };
                    put("continue;", acc)
                }
            }
        }
        _ => {
            let other = tagcase_;
            error("kfx: a self tail call where no procedure loops")
        }
    }
}

/// Expressions separated by `sep`.
pub fn put_joined(c: &'static Ctx, xs: Sexps, sep: Str, n: i64, acc: Chars) -> Chars {
    put_sep(lambda2(move |x: &'static Sexp, acc| {
        put_exp(c, x, n, value(), acc)
    }), sep, xs, acc)
}

/// A body as the inside of a block: each expression on a line of its own,
/// the last standing at `t`. A last `let`, `let*`, `begin` or `tagcase`
/// is written into the block rather than as a block of its own.
pub fn put_stmts(mut c: &'static Ctx, mut es: Sexps, mut n: i64, mut t: &'static Tail, mut acc: Chars) -> Chars {
    loop {
        let e = car(es);
        if not(null_p(cdr(es))) {
            let acc = if comment_p(e) {
                put_comment(string_chars(comment_text(e)), "//", n, true, acc)
            } else {
                put(";", put_exp(c, e, n, value(), acc))
            };
            return put_stmts(c, cdr(es), n, t, put_nl(n, acc));
        } else if (head_is_p(e, "let") || head_is_p(e, "let*")) {
            let xs = cdr(items(e));
            let names = map(&binding_name, items(car(xs)));
            (c, es, t, acc) = (with_locals(c, names), cdr(xs), hide(t, names), if head_is_p(e, "let") {
                put_let(c, items(car(xs)), n, acc)
            } else {
                put_let_star(c, items(car(xs)), n, acc)
            });
            continue;
        } else if head_is_p(e, "begin") {
            es = cdr(items(e));
            continue;
        } else if head_is_p(e, "tagcase") {
            return put_tagcase(c, cdr(items(e)), n, t, acc);
        } else {
            return put_exp(c, e, n, t, acc);
        }
    }
}

pub fn put_block(c: &'static Ctx, es: Sexps, n: i64, t: &'static Tail, acc: Chars) -> Chars {
    let acc = put_nl(i64_plus(n, 1i64), put("{", acc));
    let acc = put_stmts(c, es, i64_plus(n, 1i64), t, acc);
    put("}", put_nl(n, acc))
}

pub fn put_cond(c: &'static Ctx, clauses: Sexps, n: i64, t: &'static Tail, acc: Chars) -> Chars {
    let clause = items(car(clauses));
    if sym_is_p(car(clause), "else") {
        put_block(c, cdr(clause), n, t, acc)
    } else {
        let acc = put("if ", acc);
        let acc = put_exp(c, car(clause), n, value(), acc);
        let acc = put(" ", acc);
        let acc = put_block(c, cdr(clause), n, t, acc);
        let acc = put(" else ", acc);
        put_cond(c, cdr(clauses), n, t, acc)
    }
}

pub fn put_let1(c: &'static Ctx, binding: &'static Sexp, n: i64, acc: Chars) -> Chars {
    let acc = put("let ", acc);
    let acc = put(mangle(sym_name(car(items(binding)))), acc);
    let acc = put(" = ", acc);
    let acc = put_exp(c, second(items(binding)), n, value(), acc);
    put_nl(n, put(";", acc))
}

/// Each binding sees those before it.
pub fn put_let_star(mut c: &'static Ctx, mut bindings: Sexps, mut n: i64, mut acc: Chars) -> Chars {
    loop {
        if null_p(bindings) {
            return acc;
        } else {
            (c, bindings, acc) = (with_locals(c, map(&binding_name, cons(car(bindings), nil()))), cdr(bindings), put_let1(c, car(bindings), n, acc));
            continue;
        }
    }
}

pub fn put_binding_values(c: &'static Ctx, bindings: Sexps, n: i64, acc: Chars) -> Chars {
    let acc = put_exp(c, second(items(car(bindings))), n, value(), acc);
    if null_p(cdr(bindings)) {
        acc
    } else {
        put_binding_values(c, cdr(bindings), n, put(", ", acc))
    }
}

pub fn put_binding_names(bindings: Sexps, acc: Chars) -> Chars {
    let acc = put(mangle(sym_name(car(items(car(bindings))))), acc);
    if null_p(cdr(bindings)) {
        acc
    } else {
        put_binding_names(cdr(bindings), put(", ", acc))
    }
}

/// `let` binds in parallel: more than one binding is a tuple.
pub fn put_let(c: &'static Ctx, bindings: Sexps, n: i64, acc: Chars) -> Chars {
    if null_p(bindings) {
        acc
    } else if null_p(cdr(bindings)) {
        put_let1(c, car(bindings), n, acc)
    } else {
        let acc = put("let (", acc);
        let acc = put_binding_names(bindings, acc);
        let acc = put(") = (", acc);
        let acc = put_binding_values(c, bindings, n, acc);
        put_nl(n, put(");", acc))
    }
}

pub fn put_case_arms(c: &'static Ctx, arms: Sexps, n: i64, t: &'static Tail, acc: Chars) -> Chars {
    if null_p(arms) {
        acc
    } else {
        let arm = items(car(arms));
        let acc = put_nl(n, acc);
        let acc = if sym_is_p(car(arm), "else") {
            put("_", acc)
        } else {
            put_joined(c, items(car(arm)), " | ", n, acc)
        };
        let acc = put(" => ", acc);
        let acc = put_block(c, cdr(arm), n, t, acc);
        put_case_arms(c, cdr(arms), n, t, acc)
    }
}

pub fn put_tagcase_arms(c: &'static Ctx, arms: Sexps, n: i64, t: &'static Tail, acc: Chars) -> Chars {
    if null_p(arms) {
        acc
    } else {
        let arm = items(car(arms));
        let tag = sym_name(car(arm));
        let else_p = string_eq_p(tag, "else");
        let bound = if else_p {
            cons(sym_name(second(arm)), nil())
        } else {
            map(&sym_name, items(second(arm)))
        };
        let acc = put_nl(n, acc);
        let acc = if else_p {
            let acc = put("_ => {", acc);
            let acc = put_nl(i64_plus(n, 1i64), acc);
            let acc = put("let ", acc);
            let acc = put(mangle(sym_name(second(arm))), acc);
            put_nl(i64_plus(n, 1i64), put(" = tagcase_;", acc))
        } else {
            let acc = put(camel(tag_datatype(tag, ctx_tags(c))), acc);
            let acc = put("::", acc);
            let acc = put(camel(tag), acc);
            let acc = put("(", acc);
            let acc = put_names(items(second(arm)), acc);
            put_nl(i64_plus(n, 1i64), put(") => {", acc))
        };
        let acc = put_stmts(with_locals(c, bound), cdr(cdr(arm)), i64_plus(n, 1i64), hide(t, bound), acc);
        let acc = put("}", put_nl(n, acc));
        put_tagcase_arms(c, cdr(arms), n, t, acc)
    }
}

/// A `tagcase` as statements: its value bound once, then a `match`.
pub fn put_tagcase(c: &'static Ctx, xs: Sexps, n: i64, t: &'static Tail, acc: Chars) -> Chars {
    let acc = put("let tagcase_ = ", acc);
    let acc = put_exp(c, car(xs), n, value(), acc);
    let acc = put_nl(n, put(";", acc));
    let acc = put("match *tagcase_ {", acc);
    let acc = put_tagcase_arms(c, cdr(xs), i64_plus(n, 1i64), t, acc);
    put("}", put_nl(n, acc))
}

/// A lambda as a value: a closure, `move`, since what it captures is
/// `Copy`, made a `&'static dyn Fn` by `lambdaN`, `N` its arity.
pub fn put_lambda(c: &'static Ctx, params: Sexps, body: Sexps, n: i64, acc: Chars) -> Chars {
    let acc = put("lambda", acc);
    let acc = put(i64_to_string(size(params)), acc);
    let acc = put("(move |", acc);
    let acc = put_lambda_params(c, params, acc);
    let acc = put("| ", acc);
    put(")", put_block(with_locals(c, map(&param_name, params)), body, n, value(), acc))
}

/// `x`, or `(x T)` as `x: T`.
pub fn put_lambda_params(c: &'static Ctx, params: Sexps, acc: Chars) -> Chars {
    if null_p(params) {
        acc
    } else {
        let acc = {
            let tagcase_ = car(params);
            match *tagcase_ {
                Sexp::Lst(xt) => {
                    put_type(c, second(xt), put(": ", put(mangle(sym_name(car(xt))), acc)))
                }
                _ => {
                    let name = tagcase_;
                    put(mangle(sym_name(name)), acc)
                }
            }
        };
        put_lambda_params(c, cdr(params), if null_p(cdr(params)) {
            acc
        } else {
            put(", ", acc)
        })
    }
}

pub fn put_list(c: &'static Ctx, xs: Sexps, n: i64, acc: Chars) -> Chars {
    if null_p(xs) {
        put("nil()", acc)
    } else {
        let acc = put("cons(", acc);
        let acc = put_exp(c, car(xs), n, value(), acc);
        let acc = put(", ", acc);
        let acc = put_list(c, cdr(xs), n, acc);
        put(")", acc)
    }
}

/// `e` is the whole form, `h` its head's name and `xs` the rest.
pub fn put_form(c: &'static Ctx, e: &'static Sexp, h: Str, xs: Sexps, n: i64, t: &'static Tail, acc: Chars) -> Chars {
    if string_eq_p(h, "if") {
        let acc = put("if ", acc);
        let acc = put_exp(c, car(xs), n, value(), acc);
        let acc = put(" ", acc);
        let acc = put_block(c, cons(second(xs), nil()), n, t, acc);
        let acc = put(" else ", acc);
        put_block(c, cons(third(xs), nil()), n, t, acc)
    } else if string_eq_p(h, "cond") {
        put_cond(c, xs, n, t, acc)
    } else if string_eq_p(h, "and") {
        if null_p(xs) {
            put("true", acc)
        } else {
            put(")", put_joined(c, xs, " && ", n, put("(", acc)))
        }
    } else if string_eq_p(h, "or") {
        if null_p(xs) {
            put("false", acc)
        } else {
            put(")", put_joined(c, xs, " || ", n, put("(", acc)))
        }
    } else if (string_eq_p(h, "begin") || string_eq_p(h, "let") || string_eq_p(h, "let*") || string_eq_p(h, "tagcase")) {
        put_block(c, cons(e, nil()), n, t, acc)
    } else if string_eq_p(h, "case") {
        let acc = put("match ", acc);
        let acc = put_exp(c, car(xs), n, value(), acc);
        let acc = put(" {", acc);
        let acc = put_case_arms(c, cdr(xs), i64_plus(n, 1i64), t, acc);
        put("}", put_nl(n, acc))
    } else if string_eq_p(h, "lambda") {
        put_lambda(c, items(car(xs)), cdr(xs), n, acc)
    } else if string_eq_p(h, "list") {
        put_list(c, xs, n, acc)
    } else if string_eq_p(h, "the") {
        put_exp(c, second(xs), n, value(), acc)
    } else if null_p(xs) {
        put("()", put(mangle(h), acc))
    } else {
        put(")", put_joined(c, xs, ", ", n, put("(", put(mangle(h), acc))))
    }
}

// Top-level forms
/// Parameters, from a lambda's names and its `subr` type's; `mut` if
/// `mutable`, for a procedure that loops.
pub fn put_params(c: &'static Ctx, names: Sexps, types: Sexps, mutable: bool, acc: Chars) -> Chars {
    if null_p(names) {
        acc
    } else {
        let name = {
            let tagcase_ = car(names);
            match *tagcase_ {
                Sexp::Lst(xs) => {
                    car(xs)
                }
                _ => {
                    let other = tagcase_;
                    other
                }
            }
        };
        let acc = if mutable {
            put("mut ", acc)
        } else {
            acc
        };
        let acc = put(mangle(sym_name(name)), acc);
        let acc = put(": ", acc);
        let acc = put_type(c, car(types), acc);
        put_params(c, cdr(names), cdr(types), mutable, if null_p(cdr(names)) {
            acc
        } else {
            put(", ", acc)
        })
    }
}

/// A poly's binders as a fn's generics: a type is a Rust type parameter,
/// `Copy` and `'static` as every KFX value is; an effect is erased.
pub fn put_generics(mut binders: Sexps, mut first: bool, mut acc: Chars) -> Chars {
    loop {
        if null_p(binders) {
            if first {
                return acc;
            } else {
                return put(">", acc);
            }
        } else {
            let b = items(car(binders));
            let kind = sym_name(second(b));
            if string_eq_p(kind, "type") {
                let acc = put(if first {
                    "<"
                } else {
                    ", "
                }, acc);
                let acc = put(camel(sym_name(car(b))), acc);
                return put_generics(cdr(binders), false, put(": Copy + 'static", acc));
            } else if string_eq_p(kind, "effect") {
                binders = cdr(binders);
                continue;
            } else {
                return error(string_append("kfx: KFX-0 has no poly over a ", kind));
            }
        }
    }
}

/// A poly type's body, or a plambda's: what is under the binders.
pub fn unpoly(e: &'static Sexp) -> &'static Sexp {
    if (head_is_p(e, "poly") || head_is_p(e, "plambda")) {
        third(items(e))
    } else {
        e
    }
}

pub fn put_define(c: &'static Ctx, name: &'static Sexp, r#type: &'static Sexp, defined: &'static Sexp, acc: Chars) -> Chars {
    let binders = if head_is_p(r#type, "poly") {
        items(second(items(r#type)))
    } else {
        nil()
    };
    let r#type = unpoly(r#type);
    let defined = unpoly(defined);
    let lambda_p = head_is_p(defined, "lambda");
    let body = if lambda_p {
        cdr(cdr(items(defined)))
    } else {
        cons(defined, nil())
    };
    let doc_p = (comment_p(car(body)) && not(null_p(cdr(body))));
    let acc = if doc_p {
        put("\n", put_comment(string_chars(comment_text(car(body))), "///", 0i64, true, acc))
    } else {
        acc
    };
    let body = if doc_p {
        cdr(body)
    } else {
        body
    };
    let t = if lambda_p {
        returns(sym_name(name), map(&param_name, items(second(items(defined)))), true)
    } else {
        value()
    };
    let loops_p = (lambda_p && tail_calls_p(t, last(body)));
    let inner = if lambda_p {
        with_locals(c, map(&param_name, items(second(items(defined)))))
    } else {
        c
    };
    let acc = put("pub fn ", acc);
    let acc = put(mangle(sym_name(name)), acc);
    let acc = put_generics(binders, true, acc);
    let acc = if lambda_p {
        let acc = put("(", acc);
        let acc = put_params(c, items(second(items(defined))), items(third(items(r#type))), loops_p, acc);
        let acc = put(") -> ", acc);
        put_type(c, fourth(items(r#type)), acc)
    } else {
        put_type(c, r#type, put("() -> ", acc))
    };
    let acc = put(" {", acc);
    if loops_p {
        let acc = put_nl(2i64, put("loop {", put_nl(1i64, acc)));
        let acc = put_stmts(inner, body, 2i64, t, acc);
        put("\n    }\n}\n\n", acc)
    } else {
        put("\n}\n\n", put_stmts(inner, body, 1i64, value(), put_nl(1i64, acc)))
    }
}

pub fn put_rec(mut c: &'static Ctx, mut bindings: Sexps, mut acc: Chars) -> Chars {
    loop {
        if null_p(bindings) {
            return acc;
        } else {
            let b = items(car(bindings));
            (bindings, acc) = (cdr(bindings), put_define(c, car(b), second(b), third(b), acc));
            continue;
        }
    }
}

pub fn put_variants(c: &'static Ctx, variants: Sexps, acc: Chars) -> Chars {
    if null_p(variants) {
        acc
    } else {
        let v = items(car(variants));
        let acc = put("    ", acc);
        let acc = put(camel(sym_name(car(v))), acc);
        let acc = put("(", acc);
        let acc = put_types(c, cdr(v), acc);
        put_variants(c, cdr(variants), put("),\n", acc))
    }
}

/// Fields `f0`, `f1`, ..., from `i`, with their types if `typed`.
pub fn put_fields(c: &'static Ctx, types: Sexps, i: i64, typed: bool, acc: Chars) -> Chars {
    if null_p(types) {
        acc
    } else {
        let acc = if i64_eq(i, 0i64) {
            acc
        } else {
            put(", ", acc)
        };
        let acc = put("f", acc);
        let acc = put(i64_to_string(i), acc);
        let acc = if typed {
            put_type(c, car(types), put(": ", acc))
        } else {
            acc
        };
        put_fields(c, cdr(types), i64_plus(i, 1i64), typed, acc)
    }
}

pub fn put_constructors(c: &'static Ctx, d: Str, variants: Sexps, acc: Chars) -> Chars {
    if null_p(variants) {
        acc
    } else {
        let v = items(car(variants));
        let tag = sym_name(car(v));
        let acc = put("pub fn ", acc);
        let acc = put(mangle(tag), acc);
        let acc = put("(", acc);
        let acc = put_fields(c, cdr(v), 0i64, true, acc);
        let acc = put(") -> &'static ", acc);
        let acc = put(camel(d), acc);
        let acc = put(" {\n    alloc(", acc);
        let acc = put(camel(d), acc);
        let acc = put("::", acc);
        let acc = put(camel(tag), acc);
        let acc = put("(", acc);
        let acc = put_fields(c, cdr(v), 0i64, false, acc);
        put_constructors(c, d, cdr(variants), put("))\n}\n\n", acc))
    }
}

pub fn put_datatype(c: &'static Ctx, xs: Sexps, acc: Chars) -> Chars {
    let d = sym_name(car(xs));
    let acc = put("pub enum ", acc);
    let acc = put(camel(d), acc);
    let acc = put(" {\n", acc);
    let acc = put_variants(c, cdr(xs), acc);
    let acc = put("}\n\n", acc);
    put_constructors(c, d, cdr(xs), acc)
}

pub fn put_top(c: &'static Ctx, form: &'static Sexp, acc: Chars) -> Chars {
    let xs = items(form);
    let h = sym_name(car(xs));
    if string_eq_p(h, "define-effect") {
        acc
    } else if string_eq_p(h, "define-type") {
        let acc = put("pub type ", acc);
        let acc = put(camel(sym_name(second(xs))), acc);
        let acc = put(" = ", acc);
        let acc = put_type(c, third(xs), acc);
        put(";\n\n", acc)
    } else if string_eq_p(h, "define-datatype") {
        put_datatype(c, cdr(xs), acc)
    } else if string_eq_p(h, "define") {
        if i64_eq(size(xs), 4i64) {
            put_define(c, second(xs), third(xs), fourth(xs), acc)
        } else {
            error(string_append("kfx: a definition needs a type: ", sym_name(second(xs))))
        }
    } else if string_eq_p(h, "define-rec") {
        put_rec(c, cdr(xs), acc)
    } else {
        acc
    }
}

pub fn definition_p(e: &'static Sexp) -> bool {
    (head_is_p(e, "define") || head_is_p(e, "define-rec") || head_is_p(e, "define-datatype") || head_is_p(e, "define-type"))
}

/// A string at the top level is a comment. A procedure's documentation is
/// a string first in its body, as a Lisp docstring is: see `put-define`.
pub fn put_tops(mut c: &'static Ctx, mut forms: Sexps, mut acc: Chars) -> Chars {
    loop {
        if null_p(forms) {
            return acc;
        } else if comment_p(car(forms)) {
            let doc = (not(null_p(cdr(forms))) && definition_p(second(forms)));
            let acc = put_comment(string_chars(comment_text(car(forms))), "//", 0i64, true, acc);
            return put_tops(c, cdr(forms), put(if doc {
                "\n"
            } else {
                "\n\n"
            }, acc));
        } else {
            (forms, acc) = (cdr(forms), put_top(c, car(forms), acc));
            continue;
        }
    }
}

// Checking (TODO.md, section 13): KFX's types and effects, so that kfx
// refuses what is not KFX without Fixpt. KFX is a subset of FX-26 (PLAN.md,
// K1): this checker may refuse what FX-26 accepts, never accept what it
// refuses. Where FX-26 is clever, it is plain instead:
// - every recursive procedure says `spin` (FX-26 proves termination);
// - a call of a procedure that is a value, and a global procedure named as
// a value, are `spin` (FX-26 says when they may loop);
// - a `poly` is over types, and a list at `acyclic`.
// Bidirectional, as FX-26's checking is: `check` knows the type expected,
// `synth` finds it. A `poly` procedure's call is instantiated by
// inference variables, solved by the arguments in order, those that are
// lambdas last.
pub enum Ty {
    TyI64(),
    TyBool(),
    TyChar(),
    TyUnit(),
    TyString(),
    TyVoid(),
    TyList(&'static Ty),
    TyData(Str),
    TyProc(Strings, List<&'static Ty>, &'static Ty),
    TyVar(Str),
    TyMeta(i64),
}

pub fn ty_i64() -> &'static Ty {
    alloc(Ty::TyI64())
}

pub fn ty_bool() -> &'static Ty {
    alloc(Ty::TyBool())
}

pub fn ty_char() -> &'static Ty {
    alloc(Ty::TyChar())
}

pub fn ty_unit() -> &'static Ty {
    alloc(Ty::TyUnit())
}

pub fn ty_string() -> &'static Ty {
    alloc(Ty::TyString())
}

pub fn ty_void() -> &'static Ty {
    alloc(Ty::TyVoid())
}

pub fn ty_list(f0: &'static Ty) -> &'static Ty {
    alloc(Ty::TyList(f0))
}

pub fn ty_data(f0: Str) -> &'static Ty {
    alloc(Ty::TyData(f0))
}

pub fn ty_proc(f0: Strings, f1: List<&'static Ty>, f2: &'static Ty) -> &'static Ty {
    alloc(Ty::TyProc(f0, f1, f2))
}

pub fn ty_var(f0: Str) -> &'static Ty {
    alloc(Ty::TyVar(f0))
}

pub fn ty_meta(f0: i64) -> &'static Ty {
    alloc(Ty::TyMeta(f0))
}

// `ty-void` is `error`'s result, below every type. A `ty-proc`'s strings
// are its latent effect, a set of atoms: `spin`, `@globals` (every global
// read), and `g:` and a name (that global read). `ty-var` is a `poly`'s
// type variable, `ty-meta` an inference variable.
pub type Tys = List<&'static Ty>;

pub enum Scheme {
    Scheme(Strings, &'static Ty),
}

pub fn scheme(f0: Strings, f1: &'static Ty) -> &'static Scheme {
    alloc(Scheme::Scheme(f0, f1))
}

// A name in scope: its type, over its type variables, and where it is
// defined: `local`, `global` (the program's, so naming it reads it), or
// `prim` (kayak-rt's, and the prelude's).
pub enum Bind {
    Bind(Str, &'static Scheme, Str),
}

pub fn bind(f0: Str, f1: &'static Scheme, f2: Str) -> &'static Bind {
    alloc(Bind::Bind(f0, f1, f2))
}

pub type Binds = List<&'static Bind>;

pub enum Variant {
    Variant(Str, Tys),
}

pub fn variant(f0: Str, f1: Tys) -> &'static Variant {
    alloc(Variant::Variant(f0, f1))
}

pub type Variants = List<&'static Variant>;

pub enum Dt {
    Dt(Str, Variants),
}

pub fn dt(f0: Str, f1: Variants) -> &'static Dt {
    alloc(Dt::Dt(f0, f1))
}

pub type Dts = List<&'static Dt>;

pub enum Alias {
    Alias(Str, &'static Sexp),
}

pub fn alias(f0: Str, f1: &'static Sexp) -> &'static Alias {
    alloc(Alias::Alias(f0, f1))
}

pub type Aliases = List<&'static Alias>;

pub enum Effdef {
    Effdef(Str, Strings),
}

pub fn effdef(f0: Str, f1: Strings) -> &'static Effdef {
    alloc(Effdef::Effdef(f0, f1))
}

pub type Effdefs = List<&'static Effdef>;

// What a checker of a definition knows: the names in scope, the datatypes,
// the type abbreviations, the effect abbreviations, the definition being
// checked (for messages), and its recursive group (whose calls are `spin`).
pub enum Cv {
    Cv(Binds, Dts, Aliases, Effdefs, Str, Strings),
}

pub fn cv(f0: Binds, f1: Dts, f2: Aliases, f3: Effdefs, f4: Str, f5: Strings) -> &'static Cv {
    alloc(Cv::Cv(f0, f1, f2, f3, f4, f5))
}

// Inference variables solved so far, and the next one's number.
pub enum Sb {
    Sb(i64, &'static Ty),
}

pub fn sb(f0: i64, f1: &'static Ty) -> &'static Sb {
    alloc(Sb::Sb(f0, f1))
}

pub type Sbs = List<&'static Sb>;

pub enum St {
    St(Sbs, i64),
}

pub fn st(f0: Sbs, f1: i64) -> &'static St {
    alloc(St::St(f0, f1))
}

// What checking an expression gives: its type, its effect, and the state.
pub enum Res {
    Res(&'static Ty, Strings, &'static St),
}

pub fn res(f0: &'static Ty, f1: Strings, f2: &'static St) -> &'static Res {
    alloc(Res::Res(f0, f1, f2))
}

// Messages
pub fn show_sexp(e: &'static Sexp) -> Str {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(s) => {
            s
        }
        Sexp::Str(s) => {
            string_append("\"", string_append(s, "\""))
        }
        Sexp::Num(k) => {
            i64_to_string(k)
        }
        Sexp::Chr(c) => {
            string_append("#\\", char_to_string(c))
        }
        Sexp::Lst(xs) => {
            string_append("(", string_append(show_sexps(xs), ")"))
        }
    }
}

pub fn show_sexps(xs: Sexps) -> Str {
    if null_p(xs) {
        ""
    } else if null_p(cdr(xs)) {
        show_sexp(car(xs))
    } else {
        string_append(show_sexp(car(xs)), string_append(" ", show_sexps(cdr(xs))))
    }
}

pub fn cv_where(v: &'static Cv) -> Str {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, r#as, es, here, group) => {
            here
        }
    }
}

pub fn refuse(v: &'static Cv, message: Str) -> ! {
    error(string_append("kfx: in ", string_append(cv_where(v), string_append(": ", message))))
}

// Effects
pub fn effs_union(mut a: Strings, mut b: Strings) -> Strings {
    loop {
        if null_p(a) {
            return b;
        } else if string_member_p(car(a), b) {
            a = cdr(a);
            continue;
        } else {
            (a, b) = (cdr(a), cons(car(a), b));
            continue;
        }
    }
}

pub fn global_atom_p(x: Str) -> bool {
    char_eq_p(string_ref_i64(x, 0i64), 'g')
}

/// Whether effect `a` is within `b`: a read of one global is within a
/// read of all of them.
pub fn effs_within_p(a: Strings, b: Strings) -> bool {
    (null_p(a) || ((string_member_p(car(a), b) || (global_atom_p(car(a)) && string_member_p("@globals", b))) && effs_within_p(cdr(a), b)))
}

pub fn words_of(xs: Strings) -> Str {
    if null_p(xs) {
        ""
    } else if null_p(cdr(xs)) {
        car(xs)
    } else {
        string_append(car(xs), string_append(" ", words_of(cdr(xs))))
    }
}

pub fn show_effs(es: Strings) -> Str {
    if null_p(es) {
        "pure"
    } else {
        string_append("(", string_append(words_of(es), ")"))
    }
}

pub fn find_effdef(mut v: &'static Cv, mut name: Str, mut es: Effdefs) -> Strings {
    loop {
        if null_p(es) {
            return refuse(v, string_append("an effect KFX does not have: ", name));
        } else {
            let tagcase_ = car(es);
            match *tagcase_ {
                Effdef::Effdef(n, atoms) => {
                    if string_eq_p(n, name) {
                        return atoms;
                    } else {
                        es = cdr(es);
                        continue;
                    }
                }
            }
        }
    }
}

pub fn cv_effdefs(v: &'static Cv) -> Effdefs {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, r#as, es, here, group) => {
            es
        }
    }
}

pub fn parse_effect(v: &'static Cv, e: &'static Sexp) -> Strings {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(s) => {
            if string_eq_p(s, "pure") {
                nil()
            } else if string_eq_p(s, "spin") {
                cons("spin", nil())
            } else {
                find_effdef(v, s, cv_effdefs(v))
            }
        }
        Sexp::Lst(xs) => {
            if sym_is_p(car(xs), "maxeff") {
                parse_effects(v, cdr(xs))
            } else if (sym_is_p(car(xs), "read") && sym_is_p(second(xs), "@globals")) {
                cons("@globals", nil())
            } else if (sym_is_p(car(xs), "read") && head_is_p(second(xs), "globals")) {
                map(lambda1(move |g: &'static Sexp| {
                    string_append("g:", sym_name(g))
                }), cdr(items(second(xs))))
            } else {
                refuse(v, string_append("an effect KFX does not have: ", show_sexp(e)))
            }
        }
        _ => {
            let other = tagcase_;
            refuse(v, string_append("an effect KFX does not have: ", show_sexp(e)))
        }
    }
}

pub fn parse_effects(v: &'static Cv, es: Sexps) -> Strings {
    if null_p(es) {
        nil()
    } else {
        effs_union(parse_effect(v, car(es)), parse_effects(v, cdr(es)))
    }
}

// Types
pub fn cv_dts(v: &'static Cv) -> Dts {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, r#as, es, here, group) => {
            ds
        }
    }
}

pub fn cv_aliases(v: &'static Cv) -> Aliases {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, r#as, es, here, group) => {
            r#as
        }
    }
}

pub fn cv_binds(v: &'static Cv) -> Binds {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, r#as, es, here, group) => {
            bs
        }
    }
}

pub fn cv_group(v: &'static Cv) -> Strings {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, r#as, es, here, group) => {
            group
        }
    }
}

pub fn dt_named_p(name: Str, ds: Dts) -> bool {
    any_p(lambda1(move |d: &'static Dt| {
        let tagcase_ = d;
        match *tagcase_ {
            Dt::Dt(n, vs) => {
                string_eq_p(n, name)
            }
        }
    }), ds)
}

/// The abbreviated type, as a list of one, or none.
pub fn find_alias(mut name: Str, mut r#as: Aliases) -> Sexps {
    loop {
        if null_p(r#as) {
            return nil();
        } else {
            let tagcase_ = car(r#as);
            match *tagcase_ {
                Alias::Alias(n, t) => {
                    if string_eq_p(n, name) {
                        return cons(t, nil());
                    } else {
                        r#as = cdr(r#as);
                        continue;
                    }
                }
            }
        }
    }
}

/// `tvars`: the type variables in scope.
pub fn parse_type(mut v: &'static Cv, mut tvars: Strings, mut t: &'static Sexp) -> &'static Ty {
    loop {
        let tagcase_ = t;
        match *tagcase_ {
            Sexp::Sym(s) => {
                if string_eq_p(s, "i64") {
                    return ty_i64();
                } else if string_eq_p(s, "bool") {
                    return ty_bool();
                } else if string_eq_p(s, "char") {
                    return ty_char();
                } else if string_eq_p(s, "unit") {
                    return ty_unit();
                } else if string_eq_p(s, "string") {
                    return ty_string();
                } else if string_eq_p(s, "void") {
                    return ty_void();
                } else if string_eq_p(s, "int") {
                    return refuse(v, "KFX has no int, whose + makes a bignum; write i64, whose i64+ wraps");
                } else if string_member_p(s, tvars) {
                    return ty_var(s);
                } else if dt_named_p(s, cv_dts(v)) {
                    return ty_data(s);
                } else {
                    let found = find_alias(s, cv_aliases(v));
                    if null_p(found) {
                        return refuse(v, string_append("no type is named ", s));
                    } else {
                        t = car(found);
                        continue;
                    }
                }
            }
            Sexp::Lst(xs) => {
                if sym_is_p(car(xs), "listof") {
                    if sym_is_p(third(xs), "acyclic") {
                        return ty_list(parse_type(v, tvars, second(xs)));
                    } else {
                        return refuse(v, string_append("KFX-0's lists are at acyclic: ", show_sexp(t)));
                    }
                } else if sym_is_p(car(xs), "subr") {
                    return ty_proc(parse_effect(v, second(xs)), parse_types(v, tvars, items(third(xs))), parse_type(v, tvars, fourth(xs)));
                } else {
                    return refuse(v, string_append("a type KFX does not have: ", show_sexp(t)));
                }
            }
            _ => {
                let other = tagcase_;
                return refuse(v, string_append("a type KFX does not have: ", show_sexp(t)));
            }
        }
    }
}

pub fn parse_types(v: &'static Cv, tvars: Strings, ts: Sexps) -> Tys {
    map(lambda1(move |t: &'static Sexp| {
        parse_type(v, tvars, t)
    }), ts)
}

/// A definition's type's type variables: a poly at its top, over types.
pub fn poly_binders(v: &'static Cv, t: &'static Sexp) -> Strings {
    if head_is_p(t, "poly") {
        map(lambda1(move |b: &'static Sexp| {
            let b = items(b);
            if sym_is_p(second(b), "type") {
                sym_name(car(b))
            } else {
                refuse(v, string_append("KFX's poly is over types: ", show_sexp(lst(b))))
            }
        }), items(second(items(t))))
    } else {
        nil()
    }
}

pub fn parse_scheme(v: &'static Cv, t: &'static Sexp) -> &'static Scheme {
    let tvars = poly_binders(v, t);
    scheme(tvars, parse_type(v, tvars, if head_is_p(t, "poly") {
        third(items(t))
    } else {
        t
    }))
}

pub fn show_ty(s: &'static St, t: &'static Ty) -> Str {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyI64() => {
            "i64"
        }
        Ty::TyBool() => {
            "bool"
        }
        Ty::TyChar() => {
            "char"
        }
        Ty::TyUnit() => {
            "unit"
        }
        Ty::TyString() => {
            "string"
        }
        Ty::TyVoid() => {
            "void"
        }
        Ty::TyList(e) => {
            string_append("(listof ", string_append(show_ty(s, e), " acyclic)"))
        }
        Ty::TyData(d) => {
            d
        }
        Ty::TyProc(es, ps, r) => {
            string_append("(subr ", string_append(show_effs(es), string_append(" (", string_append(show_tys(s, ps), string_append(") ", string_append(show_ty(s, r), ")"))))))
        }
        Ty::TyVar(n) => {
            n
        }
        Ty::TyMeta(k) => {
            string_append("?", i64_to_string(k))
        }
    }
}

pub fn show_tys(s: &'static St, ts: Tys) -> Str {
    if null_p(ts) {
        ""
    } else if null_p(cdr(ts)) {
        show_ty(s, car(ts))
    } else {
        string_append(show_ty(s, car(ts)), string_append(" ", show_tys(s, cdr(ts))))
    }
}

/// `t`, its inference variable replaced by its solution, if it has one.
pub fn walk(mut s: &'static St, mut t: &'static Ty) -> &'static Ty {
    loop {
        let tagcase_ = t;
        match *tagcase_ {
            Ty::TyMeta(k) => {
                let tagcase_ = s;
                match *tagcase_ {
                    St::St(subst, next) => {
                        let found = lookup_meta(k, subst);
                        if null_p(found) {
                            return t;
                        } else {
                            t = car(found);
                            continue;
                        }
                    }
                }
            }
            _ => {
                let other = tagcase_;
                return t;
            }
        }
    }
}

pub fn lookup_meta(mut k: i64, mut subst: Sbs) -> Tys {
    loop {
        if null_p(subst) {
            return nil();
        } else {
            let tagcase_ = car(subst);
            match *tagcase_ {
                Sb::Sb(j, t) => {
                    if i64_eq(j, k) {
                        return cons(t, nil());
                    } else {
                        subst = cdr(subst);
                        continue;
                    }
                }
            }
        }
    }
}

/// Whether `t` has an inference variable not solved yet.
pub fn has_meta_p(mut s: &'static St, mut t: &'static Ty) -> bool {
    loop {
        let tagcase_ = walk(s, t);
        match *tagcase_ {
            Ty::TyMeta(k) => {
                return true;
            }
            Ty::TyList(e) => {
                t = e;
                continue;
            }
            Ty::TyProc(es, ps, r) => {
                return (has_meta_p(s, r) || any_p(lambda1(move |p: &'static Ty| {
                    has_meta_p(s, p)
                }), ps));
            }
            _ => {
                let other = tagcase_;
                return false;
            }
        }
    }
}

/// A new inference variable.
pub fn fresh(s: &'static St) -> &'static Res {
    let tagcase_ = s;
    match *tagcase_ {
        St::St(subst, next) => {
            res(ty_meta(next), nil(), st(subst, i64_plus(next, 1i64)))
        }
    }
}

pub fn solve(s: &'static St, k: i64, t: &'static Ty) -> &'static St {
    let tagcase_ = s;
    match *tagcase_ {
        St::St(subst, next) => {
            st(cons(sb(k, t), subst), next)
        }
    }
}

pub fn occurs_p(mut s: &'static St, mut k: i64, mut t: &'static Ty) -> bool {
    loop {
        let tagcase_ = walk(s, t);
        match *tagcase_ {
            Ty::TyMeta(j) => {
                return i64_eq(j, k);
            }
            Ty::TyList(e) => {
                t = e;
                continue;
            }
            Ty::TyProc(es, ps, r) => {
                return (occurs_p(s, k, r) || any_p(lambda1(move |p: &'static Ty| {
                    occurs_p(s, k, p)
                }), ps));
            }
            _ => {
                let other = tagcase_;
                return false;
            }
        }
    }
}

pub fn same_base_p(a: &'static Ty, e: &'static Ty) -> bool {
    let tagcase_ = a;
    match *tagcase_ {
        Ty::TyI64() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyI64() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyBool() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyBool() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyChar() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyChar() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyUnit() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyUnit() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyString() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyString() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// That a value of type `actual` may stand where `expected` is: the two
/// the same, inference variables solved to make them so, but for
/// `void`, which fits anything, and a procedure, whose latent effect
/// may be within the one expected.
pub fn fits(v: &'static Cv, s: &'static St, actual: &'static Ty, expected: &'static Ty) -> &'static St {
    let (a, e) = (walk(s, actual), walk(s, expected));
    let tagcase_ = a;
    match *tagcase_ {
        Ty::TyVoid() => {
            s
        }
        Ty::TyMeta(k) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyMeta(j) => {
                    if i64_eq(j, k) {
                        s
                    } else {
                        solve(s, k, e)
                    }
                }
                _ => {
                    let other = tagcase_;
                    if occurs_p(s, k, e) {
                        mismatch(v, s, a, e)
                    } else {
                        solve(s, k, e)
                    }
                }
            }
        }
        _ => {
            let other = tagcase_;
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyMeta(j) => {
                    if occurs_p(s, j, a) {
                        mismatch(v, s, a, e)
                    } else {
                        solve(s, j, a)
                    }
                }
                _ => {
                    let other = tagcase_;
                    fits_shapes(v, s, a, e)
                }
            }
        }
    }
}

pub fn fits_shapes(v: &'static Cv, s: &'static St, a: &'static Ty, e: &'static Ty) -> &'static St {
    let tagcase_ = a;
    match *tagcase_ {
        Ty::TyList(x) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyList(y) => {
                    fits(v, s, x, y)
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyData(x) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyData(y) => {
                    if string_eq_p(x, y) {
                        s
                    } else {
                        mismatch(v, s, a, e)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyVar(x) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyVar(y) => {
                    if string_eq_p(x, y) {
                        s
                    } else {
                        mismatch(v, s, a, e)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyProc(aes, aps, ar) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyProc(ees, eps, er) => {
                    if not(i64_eq(size(aps), size(eps))) {
                        mismatch(v, s, a, e)
                    } else if not(effs_within_p(aes, ees)) {
                        mismatch(v, s, a, e)
                    } else {
                        fits(v, fits_all(v, s, eps, aps), ar, er)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        _ => {
            let other = tagcase_;
            if same_base_p(a, e) {
                s
            } else {
                mismatch(v, s, a, e)
            }
        }
    }
}

/// Parameters: each expected parameter's type stands for the actual's.
pub fn fits_all(mut v: &'static Cv, mut s: &'static St, mut actuals: Tys, mut expecteds: Tys) -> &'static St {
    loop {
        if null_p(actuals) {
            return s;
        } else {
            (s, actuals, expecteds) = (fits(v, s, car(actuals), car(expecteds)), cdr(actuals), cdr(expecteds));
            continue;
        }
    }
}

pub fn mismatch(v: &'static Cv, s: &'static St, a: &'static Ty, e: &'static Ty) -> &'static St {
    refuse(v, string_append("a ", string_append(show_ty(s, a), string_append(" is here, where a ", string_append(show_ty(s, e), " is expected")))))
}

// A scheme's instance: each type variable an inference variable.
pub enum Inst {
    Inst(&'static Ty, &'static St),
}

pub fn inst(f0: &'static Ty, f1: &'static St) -> &'static Inst {
    alloc(Inst::Inst(f0, f1))
}

pub fn instantiate(s: &'static St, sc: &'static Scheme) -> &'static Inst {
    let tagcase_ = sc;
    match *tagcase_ {
        Scheme::Scheme(tvars, t) => {
            instantiate_vars(s, tvars, t)
        }
    }
}

pub fn instantiate_vars(s: &'static St, tvars: Strings, t: &'static Ty) -> &'static Inst {
    if null_p(tvars) {
        inst(t, s)
    } else {
        let tagcase_ = fresh(s);
        match *tagcase_ {
            Res::Res(m, es, s) => {
                instantiate_vars(s, cdr(tvars), replace_var(car(tvars), m, t))
            }
        }
    }
}

pub fn replace_var(name: Str, m: &'static Ty, t: &'static Ty) -> &'static Ty {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyVar(n) => {
            if string_eq_p(n, name) {
                m
            } else {
                t
            }
        }
        Ty::TyList(e) => {
            ty_list(replace_var(name, m, e))
        }
        Ty::TyProc(es, ps, r) => {
            ty_proc(es, map(lambda1(move |p: &'static Ty| {
                replace_var(name, m, p)
            }), ps), replace_var(name, m, r))
        }
        _ => {
            let other = tagcase_;
            t
        }
    }
}

// The names in scope
/// The innermost binding of `name`, as a list of one, or none.
pub fn find_bind(mut name: Str, mut bs: Binds) -> Binds {
    loop {
        if null_p(bs) {
            return nil();
        } else {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Bind::Bind(n, sc, r#where) => {
                    if string_eq_p(n, name) {
                        return cons(car(bs), nil());
                    } else {
                        bs = cdr(bs);
                        continue;
                    }
                }
            }
        }
    }
}

/// FX-26's keywords, which name nothing (fixpt's top.rs, KEYWORDS).
pub fn keyword_p(name: Str) -> bool {
    (string_eq_p(name, "lambda") || string_eq_p(name, "plambda") || string_eq_p(name, "proj") || string_eq_p(name, "if") || string_eq_p(name, "letrec") || string_eq_p(name, "let") || string_eq_p(name, "begin") || string_eq_p(name, "define") || string_eq_p(name, "define*") || string_eq_p(name, "define-type") || string_eq_p(name, "define-generative") || string_eq_p(name, "subr") || string_eq_p(name, "poly") || string_eq_p(name, "ref") || string_eq_p(name, "pairof") || string_eq_p(name, "dletrec") || string_eq_p(name, "void") || string_eq_p(name, "pure") || string_eq_p(name, "maxeff") || string_eq_p(name, "read") || string_eq_p(name, "write") || string_eq_p(name, "alloc") || string_eq_p(name, "goto") || string_eq_p(name, "comefrom") || string_eq_p(name, "region") || string_eq_p(name, "effect") || string_eq_p(name, "type") || string_eq_p(name, "prompt") || string_eq_p(name, "prompt-tag") || string_eq_p(name, "composable") || string_eq_p(name, "mark-key") || string_eq_p(name, "listof") || string_eq_p(name, "cond") || string_eq_p(name, "case") || string_eq_p(name, "else") || string_eq_p(name, "and") || string_eq_p(name, "or") || string_eq_p(name, "let*") || string_eq_p(name, "define-effect") || string_eq_p(name, "module-parameters") || string_eq_p(name, "the") || string_eq_p(name, "bloblet") || string_eq_p(name, "fields") || string_eq_p(name, "frozen") || string_eq_p(name, "arrayof") || string_eq_p(name, "icell") || string_eq_p(name, "await") || string_eq_p(name, "define-rec") || string_eq_p(name, "letrena") || string_eq_p(name, "letreap") || string_eq_p(name, "rlambda") || string_eq_p(name, "quote") || string_eq_p(name, "productof") || string_eq_p(name, "sumof") || string_eq_p(name, "product") || string_eq_p(name, "extract") || string_eq_p(name, "sum") || string_eq_p(name, "tagcase") || string_eq_p(name, "module") || string_eq_p(name, "moduleof") || string_eq_p(name, "with") || string_eq_p(name, "select") || string_eq_p(name, "load-module") || string_eq_p(name, "define-datatype") || string_eq_p(name, "make-bloblet") || string_eq_p(name, "bloblet-ref") || string_eq_p(name, "bloblet-set!") || string_eq_p(name, "bloblet-freeze") || string_eq_p(name, "bloblet-byte") || string_eq_p(name, "bloblet-set-byte!") || string_eq_p(name, "bloblet-bytes") || string_eq_p(name, "rmake-bloblet") || string_eq_p(name, "dlambda") || string_eq_p(name, "=>") || string_eq_p(name, "blobref-at") || string_eq_p(name, "blobref+") || string_eq_p(name, "blobref-owner") || string_eq_p(name, "blobref-offset") || string_eq_p(name, "blobref-get") || string_eq_p(name, "blobref-set!") || string_eq_p(name, "blobref-index") || string_eq_p(name, "blobref-variant!"))
}

pub fn bind_onto(mut xs: Binds, mut ys: Binds) -> Binds {
    loop {
        if null_p(xs) {
            return ys;
        } else {
            (xs, ys) = (cdr(xs), cons(car(xs), ys));
            continue;
        }
    }
}

pub fn with_binds(v: &'static Cv, more: Binds) -> &'static Cv {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, r#as, es, here, group) => {
            cv(bind_onto(more, bs), ds, r#as, es, here, group)
        }
    }
}

/// A local may be named by a keyword, as FX-26 has it; it may not then be
/// called, since FX-26 reads such a call as its form (`synth-call`).
pub fn local(v: &'static Cv, name: Str, t: &'static Ty) -> &'static Bind {
    bind(name, scheme(nil(), t), "local")
}

// Expressions
pub fn with_effs(r: &'static Res, es: Strings) -> &'static Res {
    let tagcase_ = r;
    match *tagcase_ {
        Res::Res(t, es0, s) => {
            res(t, effs_union(es, es0), s)
        }
    }
}

pub fn proc_type_p(s: &'static St, t: &'static Ty) -> bool {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyProc(es, ps, r) => {
            true
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// What naming a name does: a global is read, and a global procedure
/// named as a value may be called from anywhere, so may loop.
pub fn naming_effs(s: &'static St, name: Str, r#where: Str, t: &'static Ty) -> Strings {
    if not(string_eq_p(r#where, "global")) {
        nil()
    } else if proc_type_p(s, t) {
        cons("spin", cons(string_append("g:", name), nil()))
    } else {
        cons(string_append("g:", name), nil())
    }
}

pub fn literal_int(v: &'static Cv) -> ! {
    refuse(v, "a literal with nothing expected is an int, which KFX does not have: write (the i64 n)")
}

pub fn void_p(s: &'static St, t: &'static Ty) -> bool {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyVoid() => {
            true
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// What the branches after one of type `t` are checked against: the type
/// expected, if known, else `t`, unless that is `void`, which says
/// nothing.
pub fn next_expected(s: &'static St, t: &'static Ty, expected: Tys) -> Tys {
    if not(null_p(expected)) {
        expected
    } else if void_p(s, t) {
        nil()
    } else {
        cons(t, nil())
    }
}

/// The type of branches, the first of type `t` and the rest of `rest`.
pub fn joined(s: &'static St, t: &'static Ty, rest: &'static Ty, expected: Tys) -> &'static Ty {
    if not(null_p(expected)) {
        car(expected)
    } else if void_p(s, t) {
        rest
    } else {
        t
    }
}

pub fn control_form_p(h: Str) -> bool {
    (string_eq_p(h, "if") || string_eq_p(h, "cond") || string_eq_p(h, "case") || string_eq_p(h, "tagcase") || string_eq_p(h, "let") || string_eq_p(h, "let*") || string_eq_p(h, "begin"))
}

pub fn all_chars_p(xs: Sexps) -> bool {
    not(any_p(lambda1(move |x: &'static Sexp| {
        let tagcase_ = x;
        match *tagcase_ {
            Sexp::Chr(c) => {
                false
            }
            _ => {
                let other = tagcase_;
                true
            }
        }
    }), xs))
}

pub fn bind_fields(v: &'static Cv, names: Sexps, types: Tys) -> Binds {
    if null_p(names) {
        nil()
    } else {
        cons(local(v, sym_name(car(names)), car(types)), bind_fields(v, cdr(names), cdr(types)))
    }
}

pub fn bind_params(v: &'static Cv, params: Sexps, types: Tys) -> Binds {
    if null_p(params) {
        nil()
    } else {
        cons(local(v, param_name(car(params)), car(types)), bind_params(v, cdr(params), cdr(types)))
    }
}

pub fn find_dt(mut d: Str, mut ds: Dts) -> List<Variants> {
    loop {
        if null_p(ds) {
            return nil();
        } else {
            let tagcase_ = car(ds);
            match *tagcase_ {
                Dt::Dt(n, vs) => {
                    if string_eq_p(n, d) {
                        return cons(vs, nil());
                    } else {
                        ds = cdr(ds);
                        continue;
                    }
                }
            }
        }
    }
}

pub fn variants_of(v: &'static Cv, d: Str) -> Variants {
    let found = find_dt(d, cv_dts(v));
    if null_p(found) {
        refuse(v, string_append("no datatype is named ", d))
    } else {
        car(found)
    }
}

pub fn variant_fields(mut v: &'static Cv, mut d: Str, mut tag: Str, mut vs: Variants) -> Tys {
    loop {
        if null_p(vs) {
            return refuse(v, string_append(tag, string_append(" is no tag of ", string_append(d, ", or has an arm already"))));
        } else {
            let tagcase_ = car(vs);
            match *tagcase_ {
                Variant::Variant(t, fields) => {
                    if string_eq_p(t, tag) {
                        return fields;
                    } else {
                        vs = cdr(vs);
                        continue;
                    }
                }
            }
        }
    }
}

pub fn without_tag(tag: Str, vs: Variants) -> Variants {
    if null_p(vs) {
        nil()
    } else {
        let tagcase_ = car(vs);
        match *tagcase_ {
            Variant::Variant(t, fields) => {
                if string_eq_p(t, tag) {
                    cdr(vs)
                } else {
                    cons(car(vs), without_tag(tag, cdr(vs)))
                }
            }
        }
    }
}

pub fn synth(v: &'static Cv, s: &'static St, e: &'static Sexp) -> &'static Res {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Num(k) => {
            literal_int(v)
        }
        Sexp::Chr(c) => {
            res(ty_char(), nil(), s)
        }
        Sexp::Str(x) => {
            res(ty_string(), nil(), s)
        }
        Sexp::Sym(name) => {
            synth_name(v, s, name)
        }
        Sexp::Lst(xs) => {
            let tagcase_ = car(xs);
            match *tagcase_ {
                Sexp::Sym(h) => {
                    synth_form(v, s, e, h, cdr(xs))
                }
                _ => {
                    let head = tagcase_;
                    synth_call_of(v, s, synth(v, s, head), cdr(xs), cons("spin", nil()))
                }
            }
        }
    }
}

pub fn synth_name(v: &'static Cv, s: &'static St, name: Str) -> &'static Res {
    if (string_eq_p(name, "#t") || string_eq_p(name, "#f")) {
        res(ty_bool(), nil(), s)
    } else if string_eq_p(name, "#u") {
        res(ty_unit(), nil(), s)
    } else {
        let found = find_bind(name, cv_binds(v));
        if null_p(found) {
            refuse(v, string_append("nothing is named ", name))
        } else {
            let tagcase_ = car(found);
            match *tagcase_ {
                Bind::Bind(n, sc, r#where) => {
                    let tagcase_ = instantiate(s, sc);
                    match *tagcase_ {
                        Inst::Inst(t, s) => {
                            res(t, naming_effs(s, name, r#where, t), s)
                        }
                    }
                }
            }
        }
    }
}

pub fn check(v: &'static Cv, s: &'static St, e: &'static Sexp, expected: &'static Ty) -> &'static Res {
    let x = walk(s, expected);
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Num(k) => {
            let tagcase_ = x;
            match *tagcase_ {
                Ty::TyI64() => {
                    res(x, nil(), s)
                }
                Ty::TyMeta(m) => {
                    literal_int(v)
                }
                _ => {
                    let other = tagcase_;
                    refuse(v, string_append("a literal is here, where a ", string_append(show_ty(s, x), " is expected")))
                }
            }
        }
        Sexp::Lst(xs) => {
            let tagcase_ = car(xs);
            match *tagcase_ {
                Sexp::Sym(h) => {
                    check_form(v, s, e, h, cdr(xs), x)
                }
                _ => {
                    let other = tagcase_;
                    check_by_synth(v, s, e, x)
                }
            }
        }
        Sexp::Sym(name) => {
            if string_eq_p(name, "nil") {
                let tagcase_ = x;
                match *tagcase_ {
                    Ty::TyList(el) => {
                        res(x, nil(), s)
                    }
                    _ => {
                        let other = tagcase_;
                        check_by_synth(v, s, e, x)
                    }
                }
            } else {
                check_by_synth(v, s, e, x)
            }
        }
        _ => {
            let other = tagcase_;
            check_by_synth(v, s, e, x)
        }
    }
}

pub fn check_by_synth(v: &'static Cv, s: &'static St, e: &'static Sexp, expected: &'static Ty) -> &'static Res {
    let tagcase_ = synth(v, s, e);
    match *tagcase_ {
        Res::Res(t, es, s) => {
            res(expected, es, fits(v, s, t, expected))
        }
    }
}

/// A body: each expression but the last for its effect, the last
/// checked against `expected` if it has one type in it, else found.
pub fn body(v: &'static Cv, s: &'static St, es: Sexps, expected: Tys) -> &'static Res {
    if null_p(cdr(es)) {
        if null_p(expected) {
            synth(v, s, car(es))
        } else {
            check(v, s, car(es), car(expected))
        }
    } else {
        let tagcase_ = synth_any(v, s, car(es));
        match *tagcase_ {
            Res::Res(t, es0, s) => {
                with_effs(body(v, s, cdr(es), expected), es0)
            }
        }
    }
}

/// An expression whose value is dropped: a string is a comment.
pub fn synth_any(v: &'static Cv, s: &'static St, e: &'static Sexp) -> &'static Res {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Str(x) => {
            res(ty_unit(), nil(), s)
        }
        _ => {
            let other = tagcase_;
            synth(v, s, e)
        }
    }
}

pub fn synth_form(v: &'static Cv, s: &'static St, e: &'static Sexp, h: Str, xs: Sexps) -> &'static Res {
    if string_eq_p(h, "the") {
        check(v, s, second(xs), parse_type(v, nil(), car(xs)))
    } else if string_eq_p(h, "lambda") {
        synth_lambda(v, s, items(car(xs)), cdr(xs))
    } else if string_eq_p(h, "list") {
        if null_p(xs) {
            let tagcase_ = fresh(s);
            match *tagcase_ {
                Res::Res(m, es, s) => {
                    res(ty_list(m), nil(), s)
                }
            }
        } else {
            let tagcase_ = synth(v, s, car(xs));
            match *tagcase_ {
                Res::Res(t, es0, s) => {
                    with_effs(check(v, s, e, ty_list(t)), es0)
                }
            }
        }
    } else if control_form_p(h) {
        body_form(v, s, h, xs, nil())
    } else if string_eq_p(h, "and") {
        bools(v, s, xs)
    } else if string_eq_p(h, "or") {
        bools(v, s, xs)
    } else {
        synth_call(v, s, h, xs)
    }
}

pub fn check_form(v: &'static Cv, s: &'static St, e: &'static Sexp, h: Str, xs: Sexps, expected: &'static Ty) -> &'static Res {
    if control_form_p(h) {
        body_form(v, s, h, xs, cons(expected, nil()))
    } else if (string_eq_p(h, "lambda") && proc_type_p(s, expected)) {
        check_lambda(v, s, items(car(xs)), cdr(xs), walk(s, expected))
    } else if (string_eq_p(h, "list") && {
        let tagcase_ = expected;
        match *tagcase_ {
            Ty::TyList(el) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        let tagcase_ = expected;
        match *tagcase_ {
            Ty::TyList(el) => {
                res(expected, elements(v, s, xs, el), s)
            }
            _ => {
                let other = tagcase_;
                check_by_synth(v, s, e, expected)
            }
        }
    } else {
        check_by_synth(v, s, e, expected)
    }
}

/// The effect of a list's elements, each checked as `el`; the state is
/// dropped, since `el` is known.
pub fn elements(v: &'static Cv, s: &'static St, xs: Sexps, el: &'static Ty) -> Strings {
    if null_p(xs) {
        nil()
    } else {
        let tagcase_ = check(v, s, car(xs), el);
        match *tagcase_ {
            Res::Res(t, es, s) => {
                effs_union(es, elements(v, s, cdr(xs), el))
            }
        }
    }
}

pub fn bools(v: &'static Cv, s: &'static St, xs: Sexps) -> &'static Res {
    if null_p(xs) {
        res(ty_bool(), nil(), s)
    } else {
        let tagcase_ = check(v, s, car(xs), ty_bool());
        match *tagcase_ {
            Res::Res(t, es, s) => {
                with_effs(bools(v, s, cdr(xs)), es)
            }
        }
    }
}

/// `if`, `cond`, `case`, `tagcase`, `let`, `let*` and `begin`: forms
/// whose last parts give the value; `expected` is the type, if known.
pub fn body_form(v: &'static Cv, s: &'static St, h: Str, xs: Sexps, expected: Tys) -> &'static Res {
    if string_eq_p(h, "if") {
        let tagcase_ = check(v, s, car(xs), ty_bool());
        match *tagcase_ {
            Res::Res(t, es, s) => {
                with_effs(arms(v, s, cdr(xs), expected), es)
            }
        }
    } else if string_eq_p(h, "begin") {
        body(v, s, xs, expected)
    } else if string_eq_p(h, "let") {
        let_values(v, s, items(car(xs)), cdr(xs), expected, nil(), false)
    } else if string_eq_p(h, "let*") {
        let_values(v, s, items(car(xs)), cdr(xs), expected, nil(), true)
    } else if string_eq_p(h, "cond") {
        cond_clauses(v, s, xs, expected)
    } else if string_eq_p(h, "case") {
        let tagcase_ = check(v, s, car(xs), ty_char());
        match *tagcase_ {
            Res::Res(t, es, s) => {
                with_effs(case_arms(v, s, cdr(xs), expected), es)
            }
        }
    } else {
        let tagcase_ = synth(v, s, car(xs));
        match *tagcase_ {
            Res::Res(t, es, s) => {
                let tagcase_ = walk(s, t);
                match *tagcase_ {
                    Ty::TyData(d) => {
                        with_effs(tag_arms(v, s, d, cdr(xs), variants_of(v, d), expected), es)
                    }
                    _ => {
                        let other = tagcase_;
                        refuse(v, string_append("tagcase of a ", string_append(show_ty(s, t), ", no datatype")))
                    }
                }
            }
        }
    }
}

/// Branches of one type: the first found, if none is expected, and the
/// rest checked against it.
pub fn arms(v: &'static Cv, s: &'static St, branches: Sexps, expected: Tys) -> &'static Res {
    let tagcase_ = body(v, s, cons(car(branches), nil()), expected);
    match *tagcase_ {
        Res::Res(t, es, s) => {
            if null_p(cdr(branches)) {
                res(t, es, s)
            } else {
                let tagcase_ = arms(v, s, cdr(branches), next_expected(s, t, expected));
                match *tagcase_ {
                    Res::Res(t2, es2, s) => {
                        res(joined(s, t, t2, expected), effs_union(es, es2), s)
                    }
                }
            }
        }
    }
}

pub fn cond_clauses(v: &'static Cv, s: &'static St, clauses: Sexps, expected: Tys) -> &'static Res {
    let clause = items(car(clauses));
    if sym_is_p(car(clause), "else") {
        if null_p(cdr(clauses)) {
            body(v, s, cdr(clause), expected)
        } else {
            refuse(v, "a cond's else is its last clause")
        }
    } else {
        if null_p(cdr(clauses)) {
            refuse(v, "a cond needs an else: FX has no unspecified value")
        } else {
            let tagcase_ = check(v, s, car(clause), ty_bool());
            match *tagcase_ {
                Res::Res(t0, es0, s) => {
                    let tagcase_ = body(v, s, cdr(clause), expected);
                    match *tagcase_ {
                        Res::Res(t, es, s) => {
                            let tagcase_ = cond_clauses(v, s, cdr(clauses), next_expected(s, t, expected));
                            match *tagcase_ {
                                Res::Res(t2, es2, s) => {
                                    res(joined(s, t, t2, expected), effs_union(es0, effs_union(es, es2)), s)
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn case_arms(v: &'static Cv, s: &'static St, cases: Sexps, expected: Tys) -> &'static Res {
    let arm = items(car(cases));
    if sym_is_p(car(arm), "else") {
        if null_p(cdr(cases)) {
            body(v, s, cdr(arm), expected)
        } else {
            refuse(v, "a case's else is its last arm")
        }
    } else if null_p(cdr(cases)) {
        refuse(v, "a case needs an else: FX has no unspecified value")
    } else if not(all_chars_p(items(car(arm)))) {
        refuse(v, "KFX's case is on characters: FX-26's compares integers as ints")
    } else {
        let tagcase_ = body(v, s, cdr(arm), expected);
        match *tagcase_ {
            Res::Res(t, es, s) => {
                let tagcase_ = case_arms(v, s, cdr(cases), next_expected(s, t, expected));
                match *tagcase_ {
                    Res::Res(t2, es2, s) => {
                        res(joined(s, t, t2, expected), effs_union(es, es2), s)
                    }
                }
            }
        }
    }
}

/// A tagcase's arms; `vs` are the variants no arm has taken yet.
pub fn tag_arms(v: &'static Cv, s: &'static St, d: Str, tagged: Sexps, vs: Variants, expected: Tys) -> &'static Res {
    if null_p(tagged) {
        if null_p(vs) {
            if null_p(expected) {
                refuse(v, "a tagcase with no arms")
            } else {
                res(car(expected), nil(), s)
            }
        } else {
            refuse(v, string_append("a tagcase of a ", string_append(d, " with no else, and no arm for each tag")))
        }
    } else {
        let arm = items(car(tagged));
        let tag = sym_name(car(arm));
        if string_eq_p(tag, "else") {
            if null_p(cdr(tagged)) {
                body(with_binds(v, cons(local(v, sym_name(second(arm)), ty_data(d)), nil())), s, cdr(cdr(arm)), expected)
            } else {
                refuse(v, "a tagcase's else is its last arm")
            }
        } else {
            let fields = variant_fields(v, d, tag, vs);
            let names = items(second(arm));
            if not(i64_eq(size(names), size(fields))) {
                refuse(v, string_append("the arm for ", string_append(tag, " names the wrong number of fields")))
            } else {
                let tagcase_ = body(with_binds(v, bind_fields(v, names, fields)), s, cdr(cdr(arm)), expected);
                match *tagcase_ {
                    Res::Res(t, es, s) => {
                        let tagcase_ = tag_arms(v, s, d, cdr(tagged), without_tag(tag, vs), next_expected(s, t, expected));
                        match *tagcase_ {
                            Res::Res(t2, es2, s) => {
                                res(joined(s, t, t2, expected), effs_union(es, es2), s)
                            }
                        }
                    }
                }
            }
        }
    }
}

/// A `let`'s or `let*`'s bindings, then its body. `bound`: those made
/// so far, which a `let*`'s next binding sees and a `let`'s does not.
pub fn let_values(v: &'static Cv, s: &'static St, bindings: Sexps, forms: Sexps, expected: Tys, bound: Binds, sequential: bool) -> &'static Res {
    if null_p(bindings) {
        body(with_binds(v, bound), s, forms, expected)
    } else {
        let b = items(car(bindings));
        let sees = if sequential {
            with_binds(v, bound)
        } else {
            v
        };
        let tagcase_ = synth(sees, s, second(b));
        match *tagcase_ {
            Res::Res(t, es, s) => {
                with_effs(let_values(v, s, cdr(bindings), forms, expected, cons(local(v, sym_name(car(b)), t), bound), sequential), es)
            }
        }
    }
}

/// A lambda with nothing expected: its parameters' types written.
pub fn synth_lambda(v: &'static Cv, s: &'static St, params: Sexps, forms: Sexps) -> &'static Res {
    let types = map(lambda1(move |p: &'static Sexp| {
        let tagcase_ = p;
        match *tagcase_ {
            Sexp::Lst(pt) => {
                parse_type(v, nil(), second(pt))
            }
            _ => {
                let other = tagcase_;
                refuse(v, string_append("a lambda with nothing expected needs its parameters' types: ", show_sexp(other)))
            }
        }
    }), params);
    let tagcase_ = body(with_binds(v, bind_params(v, params, types)), s, forms, nil());
    match *tagcase_ {
        Res::Res(r, es, s) => {
            res(ty_proc(es, types, r), nil(), s)
        }
    }
}

pub fn check_lambda(v: &'static Cv, s: &'static St, params: Sexps, forms: Sexps, expected: &'static Ty) -> &'static Res {
    let tagcase_ = expected;
    match *tagcase_ {
        Ty::TyProc(ees, eps, er) => {
            if not(i64_eq(size(params), size(eps))) {
                refuse(v, "a lambda of the wrong number of parameters")
            } else {
                let s = check_written_params(v, s, params, eps);
                let tagcase_ = body(with_binds(v, bind_params(v, params, eps)), s, forms, cons(er, nil()));
                match *tagcase_ {
                    Res::Res(r, es, s) => {
                        if effs_within_p(es, ees) {
                            res(expected, nil(), s)
                        } else {
                            refuse(v, string_append("a lambda whose effect ", string_append(show_effs(es), string_append(" is not within ", show_effs(ees)))))
                        }
                    }
                }
            }
        }
        _ => {
            let other = tagcase_;
            refuse(v, "a lambda where no procedure is expected")
        }
    }
}

/// A parameter written `(x T)` must be of the type expected. One written
/// `x` must have its type known already, from the arguments before the
/// lambda: rustc, which checks a call's arguments in order, finds a
/// closure's parameter types no other way.
pub fn check_written_params(mut v: &'static Cv, mut s: &'static St, mut params: Sexps, mut types: Tys) -> &'static St {
    loop {
        if null_p(params) {
            return s;
        } else {
            (s, params, types) = ({
                let tagcase_ = car(params);
                match *tagcase_ {
                    Sexp::Lst(pt) => {
                        fits(v, s, car(types), parse_type(v, nil(), second(pt)))
                    }
                    _ => {
                        let other = tagcase_;
                        if has_meta_p(s, car(types)) {
                            refuse(v, string_append("the type of the lambda's parameter ", string_append(show_sexp(other), " is not known from the arguments before it: write it as (x T)")))
                        } else {
                            s
                        }
                    }
                }
            }, cdr(params), cdr(types));
            continue;
        }
    }
}

/// A call of a name: a procedure in this group is `spin`, one that is a
/// local's value is a call of a procedure not known, so `spin` too.
pub fn synth_call(v: &'static Cv, s: &'static St, h: Str, args: Sexps) -> &'static Res {
    let found = find_bind(h, cv_binds(v));
    if keyword_p(h) {
        refuse(v, string_append("a call of ", string_append(h, ", which FX-26 reads as its form, not a call")))
    } else if null_p(found) {
        refuse(v, string_append("nothing is named ", h))
    } else {
        let tagcase_ = car(found);
        match *tagcase_ {
            Bind::Bind(n, sc, r#where) => {
                let tagcase_ = instantiate(s, sc);
                match *tagcase_ {
                    Inst::Inst(t, s) => {
                        synth_call_of(v, s, res(t, nil(), s), args, effs_union(if string_eq_p(r#where, "global") {
                            cons(string_append("g:", h), nil())
                        } else {
                            nil()
                        }, if (string_eq_p(r#where, "local") || string_member_p(h, cv_group(v))) {
                            cons("spin", nil())
                        } else {
                            nil()
                        }))
                    }
                }
            }
        }
    }
}

/// A call of the procedure `callee` is: its arguments checked against
/// its parameters, in order; its effect, the callee's latent effect, the
/// arguments' and `more`. In order, not lambdas last as FX-26 does,
/// since rustc finds a closure's parameter types only from what comes
/// before it: see `check-written-params`.
pub fn synth_call_of(v: &'static Cv, s: &'static St, callee: &'static Res, args: Sexps, more: Strings) -> &'static Res {
    let tagcase_ = callee;
    match *tagcase_ {
        Res::Res(t, es0, s) => {
            let tagcase_ = walk(s, t);
            match *tagcase_ {
                Ty::TyProc(latent, ps, r) => {
                    if not(i64_eq(size(ps), size(args))) {
                        refuse(v, string_append("a call of the wrong number of arguments: ", show_sexps(args)))
                    } else {
                        let tagcase_ = call_args(v, s, args, ps);
                        match *tagcase_ {
                            Res::Res(u, es1, s) => {
                                res(r, effs_union(latent, effs_union(more, effs_union(es0, es1))), s)
                            }
                        }
                    }
                }
                _ => {
                    let other = tagcase_;
                    refuse(v, string_append("a call of a ", string_append(show_ty(s, t), ", no procedure")))
                }
            }
        }
    }
}

pub fn call_args(v: &'static Cv, s: &'static St, args: Sexps, ps: Tys) -> &'static Res {
    if null_p(args) {
        res(ty_unit(), nil(), s)
    } else {
        let tagcase_ = check(v, s, car(args), car(ps));
        match *tagcase_ {
            Res::Res(t, es, s) => {
                with_effs(call_args(v, s, cdr(args), cdr(ps)), es)
            }
        }
    }
}

// Definitions
pub fn primitives() -> Str {
    "(i64+ (subr pure (i64 i64) i64)) (i64- (subr pure (i64 i64) i64)) (i64* (subr pure (i64 i64) i64))\n   (i64-quotient (subr pure (i64 i64) i64)) (i64-remainder (subr pure (i64 i64) i64))\n   (i64-and (subr pure (i64 i64) i64)) (i64-or (subr pure (i64 i64) i64)) (i64-xor (subr pure (i64 i64) i64))\n   (i64-not (subr pure (i64) i64))\n   (i64= (subr pure (i64 i64) bool)) (i64< (subr pure (i64 i64) bool)) (i64> (subr pure (i64 i64) bool))\n   (i64<= (subr pure (i64 i64) bool)) (i64>= (subr pure (i64 i64) bool))\n   (not (subr pure (bool) bool))\n   (char=? (subr pure (char char) bool)) (char-whitespace? (subr pure (char) bool))\n   (char-numeric? (subr pure (char) bool)) (char-alphabetic? (subr pure (char) bool))\n   (char-upcase (subr pure (char) char)) (char->string (subr pure (char) string))\n   (string-append (subr pure (string string) string)) (string=? (subr pure (string string) bool))\n   (list->string (subr pure ((listof char acyclic)) string))\n   (error (subr pure (string) void))\n   (string-length-i64 (subr pure (string) i64)) (string-ref-i64 (subr pure (string i64) char))\n   (char->i64 (subr pure (char) i64)) (i64->string (subr pure (i64) string))\n   (nil (poly ((t type)) (listof t acyclic)))\n   (cons (poly ((t type)) (subr pure (t (listof t acyclic)) (listof t acyclic))))\n   (car (poly ((t type)) (subr pure ((listof t acyclic)) t)))\n   (cdr (poly ((t type)) (subr pure ((listof t acyclic)) (listof t acyclic))))\n   (null? (poly ((t type)) (subr pure ((listof t acyclic)) bool)))"
}

// kayak-rt's primitives at KFX's types: the prelude's (kfx/prelude.fx), and
// FX-26's standard environment's at `acyclic`, where making and reading
// lists are pure.
pub fn prim_binds(v: &'static Cv) -> Binds {
    map(lambda1(move |p: &'static Sexp| {
        let xs = items(p);
        bind(sym_name(car(xs)), parse_scheme(v, second(xs)), "prim")
    }), read_all(string_chars(primitives())))
}

/// A define-datatype's name and variants.
pub fn datatype_of(v: &'static Cv, xs: Sexps) -> &'static Dt {
    dt(sym_name(car(xs)), map(lambda1(move |vt: &'static Sexp| {
        let ys = items(vt);
        variant(sym_name(car(ys)), parse_types(v, nil(), cdr(ys)))
    }), cdr(xs)))
}

pub fn constructors(d: &'static Dt) -> Binds {
    let tagcase_ = d;
    match *tagcase_ {
        Dt::Dt(name, vs) => {
            map(lambda1(move |vt: &'static Variant| {
                let tagcase_ = vt;
                match *tagcase_ {
                    Variant::Variant(tag, fields) => {
                        bind(tag, scheme(nil(), ty_proc(nil(), fields, ty_data(name))), "global")
                    }
                }
            }), vs)
        }
    }
}

// Types and datatypes are declared ahead: every one is in scope in every
// definition, as FX-26 has it. Effect abbreviations and values are seen
// only after their definitions.
pub fn declare_types(mut forms: Sexps, mut r#as: Aliases) -> Aliases {
    loop {
        if null_p(forms) {
            return r#as;
        } else if head_is_p(car(forms), "define-type") {
            let xs = items(car(forms));
            (forms, r#as) = (cdr(forms), cons(alias(sym_name(second(xs)), third(xs)), r#as));
            continue;
        } else {
            forms = cdr(forms);
            continue;
        }
    }
}

/// The datatypes' names, before their variants' types can be read.
pub fn datatype_names(mut forms: Sexps, mut ds: Dts) -> Dts {
    loop {
        if null_p(forms) {
            return ds;
        } else if head_is_p(car(forms), "define-datatype") {
            (forms, ds) = (cdr(forms), cons(dt(sym_name(second(items(car(forms)))), nil()), ds));
            continue;
        } else {
            forms = cdr(forms);
            continue;
        }
    }
}

/// `v`, with a define-effect's abbreviation.
pub fn with_effdef(v: &'static Cv, xs: Sexps) -> &'static Cv {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, r#as, es, here, group) => {
            cv(bs, ds, r#as, cons(effdef(sym_name(second(xs)), parse_effect(v, third(xs))), es), here, group)
        }
    }
}

/// Each datatype's variants' types, as an effect abbreviation before it
/// has them read.
pub fn declare_datatypes(mut v: &'static Cv, mut forms: Sexps, mut ds: Dts) -> Dts {
    loop {
        if null_p(forms) {
            return ds;
        } else if head_is_p(car(forms), "define-datatype") {
            (forms, ds) = (cdr(forms), cons(datatype_of(v, cdr(items(car(forms)))), ds));
            continue;
        } else if head_is_p(car(forms), "define-effect") {
            (v, forms) = (with_effdef(v, items(car(forms))), cdr(forms));
            continue;
        } else {
            forms = cdr(forms);
            continue;
        }
    }
}

pub fn at(v: &'static Cv, here: Str, group: Strings) -> &'static Cv {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, r#as, es, h, g) => {
            cv(bs, ds, r#as, es, here, group)
        }
    }
}

/// kayak-rt's own names, which the generated modules import with the
/// program's: a global of one of them would be ambiguous in Rust.
pub fn runtime_name_p(name: Str) -> bool {
    (string_eq_p(name, "alloc") || string_eq_p(name, "leak-string") || string_eq_p(name, "with-big-stack") || string_eq_p(name, "lambda0") || string_eq_p(name, "lambda1") || string_eq_p(name, "lambda2") || string_eq_p(name, "lambda3") || string_eq_p(name, "lambda4"))
}

/// A global, defined once: the generated modules each import every
/// other's names and kayak-rt's, so a name defined twice, or a
/// primitive's, would be ambiguous in Rust. KFX has no redefinition.
pub fn global(v: &'static Cv, name: Str, sc: &'static Scheme) -> &'static Bind {
    if keyword_p(name) {
        refuse(v, string_append("a keyword names nothing: ", name))
    } else if runtime_name_p(name) {
        refuse(v, string_append("kayak-rt has a ", string_append(name, " of its own")))
    } else {
        let found = find_bind(name, cv_binds(v));
        if null_p(found) {
            bind(name, sc, "global")
        } else {
            let tagcase_ = car(found);
            match *tagcase_ {
                Bind::Bind(n, sc0, r#where) => {
                    if string_eq_p(r#where, "prim") {
                        refuse(v, string_append(name, " is a primitive, which KFX does not define again"))
                    } else {
                        refuse(v, string_append(name, " is defined already: KFX defines each name once"))
                    }
                }
            }
        }
    }
}

/// `v` with each of `bs`, each refused if its name is taken (`global`).
pub fn defined_once(mut v: &'static Cv, mut bs: Binds) -> &'static Cv {
    loop {
        if null_p(bs) {
            return v;
        } else {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Bind::Bind(n, sc, r#where) => {
                    (v, bs) = (with_binds(v, cons(global(v, n, sc), nil())), cdr(bs));
                    continue;
                }
            }
        }
    }
}

pub fn new_state() -> &'static St {
    st(nil(), 0i64)
}

/// A procedure's lambda against its type; `v` already has its name.
pub fn check_procedure(v: &'static Cv, defined: &'static Sexp, sc: &'static Scheme) -> &'static Cv {
    let lam = items(if head_is_p(defined, "plambda") {
        third(items(defined))
    } else {
        defined
    });
    let tagcase_ = sc;
    match *tagcase_ {
        Scheme::Scheme(tvars, t) => {
            let tagcase_ = check_lambda(v, new_state(), items(second(lam)), cdr(cdr(lam)), t);
            match *tagcase_ {
                Res::Res(u, es, s) => {
                    v
                }
            }
        }
    }
}

pub fn variants_dt(v: &'static Cv, d: Str) -> List<&'static Dt> {
    let found = find_dt(d, cv_dts(v));
    if null_p(found) {
        refuse(v, string_append("no datatype is named ", d))
    } else {
        cons(dt(d, car(found)), nil())
    }
}

/// A define-rec: every member in scope in each, and each a lambda.
pub fn check_rec(v: &'static Cv, bindings: Sexps) -> &'static Cv {
    let names = map(lambda1(move |b: &'static Sexp| {
        sym_name(car(items(b)))
    }), bindings);
    let named = with_binds(v, map(lambda1(move |b: &'static Sexp| {
        let ys = items(b);
        global(v, sym_name(car(ys)), parse_scheme(v, second(ys)))
    }), bindings));
    map(lambda1(move |b: &'static Sexp| {
        let ys = items(b);
        if procedure_p(third(ys)) {
            check_procedure(at(named, sym_name(car(ys)), names), third(ys), parse_scheme(v, second(ys)))
        } else {
            refuse(v, "a define-rec binds only lambdas")
        }
    }), bindings);
    named
}

/// One top-level form, which may add to what the forms after it see.
pub fn check_top(v: &'static Cv, form: &'static Sexp) -> &'static Cv {
    let tagcase_ = form;
    match *tagcase_ {
        Sexp::Str(x) => {
            v
        }
        Sexp::Lst(xs) => {
            let h = if null_p(xs) {
                ""
            } else {
                let tagcase_ = car(xs);
                match *tagcase_ {
                    Sexp::Sym(n) => {
                        n
                    }
                    _ => {
                        let other = tagcase_;
                        ""
                    }
                }
            };
            if string_eq_p(h, "define-effect") {
                with_effdef(v, xs)
            } else if string_eq_p(h, "define-type") {
                v
            } else if string_eq_p(h, "define-datatype") {
                let d = car(variants_dt(v, sym_name(second(xs))));
                defined_once(v, constructors(d))
            } else if string_eq_p(h, "define") {
                if not(i64_eq(size(xs), 4i64)) {
                    refuse(v, "a definition needs a type")
                } else {
                    let name = sym_name(second(xs));
                    let v = at(v, name, cons(name, nil()));
                    let sc = parse_scheme(v, third(xs));
                    let named = with_binds(v, cons(global(v, name, sc), nil()));
                    if procedure_p(fourth(xs)) {
                        check_procedure(named, fourth(xs), sc)
                    } else {
                        let tagcase_ = sc;
                        match *tagcase_ {
                            Scheme::Scheme(tvars, t) => {
                                if null_p(tvars) {
                                    let tagcase_ = check(v, new_state(), fourth(xs), t);
                                    match *tagcase_ {
                                        Res::Res(u, es, s) => {
                                            named
                                        }
                                    }
                                } else {
                                    refuse(v, "a poly constant: only a procedure may be poly")
                                }
                            }
                        }
                    }
                }
            } else if string_eq_p(h, "define-rec") {
                check_rec(v, cdr(xs))
            } else {
                let tagcase_ = synth(at(v, "a top-level expression", nil()), new_state(), form);
                match *tagcase_ {
                    Res::Res(t, es, s) => {
                        v
                    }
                }
            }
        }
        _ => {
            let other = tagcase_;
            let tagcase_ = synth(at(v, "a top-level expression", nil()), new_state(), form);
            match *tagcase_ {
                Res::Res(t, es, s) => {
                    v
                }
            }
        }
    }
}

/// No type is named as one of kayak-rt's: `Str`, `List`, `Cons`.
pub fn type_names_free(v: &'static Cv, forms: Sexps) -> () {
    map(lambda1(move |f: &'static Sexp| {
        if (head_is_p(f, "define-type") || head_is_p(f, "define-datatype")) {
            let name = {
                let tagcase_ = second(items(f));
                match *tagcase_ {
                    Sexp::Sym(n) => {
                        n
                    }
                    _ => {
                        let other = tagcase_;
                        ""
                    }
                }
            };
            if (string_eq_p(name, "str") || string_eq_p(name, "list") || string_eq_p(name, "cons")) {
                refuse(v, string_append("kayak-rt has a type ", string_append(camel(name), " of its own")))
            } else {
                ()
            }
        } else {
            ()
        }
    }), forms);
    ()
}

pub fn check_tops(mut v: &'static Cv, mut forms: Sexps) -> &'static Cv {
    loop {
        if null_p(forms) {
            return v;
        } else {
            (v, forms) = (check_top(v, car(forms)), cdr(forms));
            continue;
        }
    }
}

/// Every form, in order; the first error stops the compiler.
pub fn check_program(forms: Sexps) -> () {
    let start = cv(nil(), nil(), declare_types(forms, nil()), nil(), "a type", nil());
    let types = type_names_free(start, forms);
    let named = {
        let tagcase_ = start;
        match *tagcase_ {
            Cv::Cv(bs, ds, r#as, es, here, group) => {
                cv(bs, datatype_names(forms, nil()), r#as, es, here, group)
            }
        }
    };
    let typed = {
        let tagcase_ = named;
        match *tagcase_ {
            Cv::Cv(bs, ds, r#as, es, here, group) => {
                cv(bs, declare_datatypes(named, forms, nil()), r#as, es, here, group)
            }
        }
    };
    let v = with_binds(typed, prim_binds(typed));
    check_tops(v, forms);
    ()
}

pub fn header() -> Str {
    "// Generated by kfx from KFX-0 source: edit that, and regenerate (PLAN.md, section 1).\n\nuse kayak_rt::*;\n\n"
}

/// A KFX-0 program's text, as Rust.
pub fn compile(src: Str) -> Str {
    let forms = read_all(string_chars(src));
    let checked = check_program(forms);
    let c = collect(forms, ctx(nil(), nil(), nil(), nil()));
    rev_to_string(put_tops(c, forms, put(header(), nil())))
}

// Programs of several files. A program is files in order, as a manifest
// (NAME.unit) lists them: to FX-26, the files one after another, so that a
// definition sees those in the files before it. To Rust, a module each,
// which imports every other's names (`use super::*`) and kayak-rt's; the
// modules' `mod.rs` declares them and re-exports their names.

// A file's name, without `.kfx`, and its text; a Rust file's name, and its
// text.
pub enum Source {
    Source(Str, Str),
}

pub fn source(f0: Str, f1: Str) -> &'static Source {
    alloc(Source::Source(f0, f1))
}

pub enum Output {
    Output(Str, Str),
}

pub fn output(f0: Str, f1: Str) -> &'static Output {
    alloc(Output::Output(f0, f1))
}

pub type Sources = List<&'static Source>;

pub type Outputs = List<&'static Output>;

pub fn onto<A: Copy + 'static>(xs: List<A>, ys: List<A>) -> List<A> {
    if null_p(xs) {
        ys
    } else {
        cons(car(xs), onto(cdr(xs), ys))
    }
}

pub fn concat<A: Copy + 'static>(xss: List<List<A>>) -> List<A> {
    if null_p(xss) {
        nil()
    } else {
        onto(car(xss), concat(cdr(xss)))
    }
}

pub fn source_forms(s: &'static Source) -> Sexps {
    let tagcase_ = s;
    match *tagcase_ {
        Source::Source(name, text) => {
            read_all(string_chars(text))
        }
    }
}

pub fn module_header() -> Str {
    "// Generated by kfx from KFX-0 source: edit that, and regenerate (PLAN.md, section 1).\n\nuse kayak_rt::*;\nuse super::*;\n\n"
}

pub fn put_mods(ss: Sources, acc: Chars) -> Chars {
    if null_p(ss) {
        acc
    } else {
        let tagcase_ = car(ss);
        match *tagcase_ {
            Source::Source(name, text) => {
                let m = mangle(name);
                let acc = put("pub mod ", acc);
                let acc = put(m, acc);
                let acc = put(";\npub use ", acc);
                let acc = put(m, acc);
                put_mods(cdr(ss), put("::*;\n", acc))
            }
        }
    }
}

/// A program of several files, as Rust: its modules, then their `mod.rs`.
/// The whole program is checked, and each file written as a module.
pub fn compile_units(ss: Sources) -> Outputs {
    let forms = concat(map(lambda1(move |s: &'static Source| {
        source_forms(s)
    }), ss));
    let checked = check_program(forms);
    let c = collect(forms, ctx(nil(), nil(), nil(), nil()));
    let modules = map(lambda1(move |s: &'static Source| {
        let tagcase_ = s;
        match *tagcase_ {
            Source::Source(name, text) => {
                output(string_append(mangle(name), ".rs"), rev_to_string(put_tops(c, source_forms(s), put(module_header(), nil()))))
            }
        }
    }), ss);
    onto(modules, cons(output("mod.rs", rev_to_string(put_mods(ss, put("// Generated by kfx: the program's modules (PLAN.md, section 1).\n\n", nil())))), nil()))
}

/// Outputs as one string, for stage 0, where Fixpt prints one: each a line
/// `@@kfx-file NAME`, then its text. No line of generated Rust starts with
/// `@@`, since its string literals hold no newline but escaped.
pub fn bundle(os: Outputs) -> Str {
    if null_p(os) {
        ""
    } else {
        let tagcase_ = car(os);
        match *tagcase_ {
            Output::Output(name, text) => {
                string_append("@@kfx-file ", string_append(name, string_append("\n", string_append(text, bundle(cdr(os))))))
            }
        }
    }
}

